	if out, stderr, err := runManagedCobra(t, pushCmd(), []string{"old", "--only", "entry", "--dry-run"}, nil); err != nil {
		t.Fatalf("healthy scoped fallback preview: %v\n%s\n%s", err, out, stderr)
	}
