	internal.ScopedPushCheckpoint = func(step string, _ int) error {
		if step == "before-push" && !fired {
			fired = true
			gitRun(t, f.repo, "push", "origin", advance+":refs/heads/B")
			gitRun(t, f.repo, "fetch", "origin")
		}
		return nil
	}
