// TestSyncPlanDocs_ChangelogRecoveryCellsAreSeparateItems
// ---------------------------------------------------------------------------

// changelogUnreleasedBullets splits CHANGELOG.md's "## Unreleased" section
// into its top-level "- " bulleted items, so callers can assert content
// scoped to one bullet rather than the whole section (which would let two
// merged cells masquerade as three).
func changelogUnreleasedBullets(t *testing.T) []string {
	t.Helper()
	content := readRepoDoc(t, "CHANGELOG.md")
	start := strings.Index(content, "## Unreleased")
	if start < 0 {
		t.Fatal("CHANGELOG.md must have an \"## Unreleased\" section")
	}
	rest := content[start:]
	headingRe := regexp.MustCompile(`(?m)^## `)
	headings := headingRe.FindAllStringIndex(rest, -1)
	block := rest
	if len(headings) >= 2 {
		block = rest[:headings[1][0]]
	}
	bulletRe := regexp.MustCompile(`(?m)^- `)
	locs := bulletRe.FindAllStringIndex(block, -1)
	if len(locs) == 0 {
		t.Fatal("no top-level bullets found in CHANGELOG.md's Unreleased section")
	}
	bullets := make([]string, 0, len(locs))
	for i, loc := range locs {
		end := len(block)
		if i+1 < len(locs) {
			end = locs[i+1][0]
		}
		bullets = append(bullets, block[loc[0]:end])
	}
	return bullets
}

// TestSyncPlanDocs_ChangelogRecoveryCellsAreSeparateItems implements
// spec.md §22.33-i-a: the CHANGELOG.md Unreleased entry must disclose all
// three no-flag recovery cells (cell 1, cell 7, cell 4 — sync_recovery_test.go's
// Case1/Case7/Cell4 coverage) as three separate bullets, each carrying its
// own required content. The spec states plainly that "a check that finds
// cell 1 and cell 7 but not cell 4 fails"; this test encodes that literally
// by asserting each cell's disclosure independently, so dropping any one
// cell's content — or merging two cells into one bullet — fails on its own,
// never masked by the other two passing.
func TestSyncPlanDocs_ChangelogRecoveryCellsAreSeparateItems(t *testing.T) {
	full := strings.ToLower(readRepoDoc(t, "CHANGELOG.md"))
	for _, marker := range []string{"recovery cell 1", "recovery cell 7", "recovery cell 4"} {
		if n := strings.Count(full, marker); n != 1 {
			t.Fatalf("CHANGELOG.md must name %q exactly once, found %d", marker, n)
		}
	}

	bullets := changelogUnreleasedBullets(t)
	find := func(marker string) (int, string) {
		for i, b := range bullets {
			if strings.Contains(strings.ToLower(b), marker) {
				return i, b
			}
		}
		t.Fatalf("no CHANGELOG.md bullet in ## Unreleased names %q", marker)
		return -1, ""
	}

	idx1, bullet1 := find("recovery cell 1")
	idx7, bullet7 := find("recovery cell 7")
	idx4, bullet4 := find("recovery cell 4")

	if idx1 == idx7 || idx1 == idx4 || idx7 == idx4 {
		t.Fatalf("recovery cells 1, 7 and 4 must be three separate CHANGELOG bullets; got bullet indices %d, %d, %d", idx1, idx7, idx4)
	}

	n1 := normalizeProse(bullet1)
	if !strings.Contains(n1, "nothing to abort") || !strings.Contains(n1, "no sync in progress") {
		t.Errorf("cell 1 bullet must disclose the previous \"Nothing to abort — no sync in progress.\" wording:\n%s", bullet1)
	}
	if !strings.Contains(n1, "stale sync guard from pid <pid> cleared; no sync state was present.") {
		t.Errorf("cell 1 bullet must quote the new stale-guard message (normalized):\n%s", bullet1)
	}

	n7 := normalizeProse(bullet7)
	if !strings.Contains(n7, "clears both") {
		t.Errorf("cell 7 bullet must disclose that --abort now clears both artefacts:\n%s", bullet7)
	}
	if !strings.Contains(n7, "sync state cleared; stale sync guard from pid <pid> cleared.") {
		t.Errorf("cell 7 bullet must quote the combined-clear message (normalized):\n%s", bullet7)
	}

	n4 := normalizeProse(bullet4)
	if !strings.Contains(n4, "--continue") || !strings.Contains(n4, "--abort") {
		t.Errorf("cell 4 bullet must name both recovery verbs, --continue and --abort:\n%s", bullet4)
	}
	if !strings.Contains(n4, "the interrupted guarded setup's backup of the previous sync state was discarded") {
		t.Errorf("cell 4 bullet must quote the discard sentence (normalized):\n%s", bullet4)
	}
	if !strings.Contains(n4, "refuses the same residue or discards the backup") {
		t.Errorf("cell 4 bullet must disclose the older-release downgrade note:\n%s", bullet4)
	}
}

// TestSyncPlanDocs_ChangelogCheckoutDowngradeSentenceIsContinueOnly pins the
// one attribution §13.6 rule 5's old-binary table makes and the CHANGELOG
// must not blur: the checkout version-comparison sentence
// `checkout sync transaction state version 3 is newer than 2; upgrade tws or
// remove <path>` is the OLD binary's `--continue` answer alone. A FRESH old
// binary run over the same transaction never reaches that comparison — it
// refuses earlier, at HasCheckoutTransaction, with the shipped
// `previous checkout-sync incomplete; use --continue or --abort`.
//
// A CHANGELOG that attributes the version sentence to "fresh/--continue"
// would tell an operator to expect words a fresh run never prints, so the
// two sentences are asserted to be attributed separately here, and the
// version sentence is asserted NOT to be attributed to a fresh run.
func TestSyncPlanDocs_ChangelogCheckoutDowngradeSentenceIsContinueOnly(t *testing.T) {
	const versionSentence = "checkout sync transaction state version 3 is newer than 2; upgrade tws or remove <path>"
	const freshSentence = "previous checkout-sync incomplete; use --continue or --abort"

	full := normalizeProse(readRepoDoc(t, "CHANGELOG.md"))
	if !strings.Contains(full, strings.ToLower(versionSentence)) {
		t.Fatalf("CHANGELOG.md must quote the checkout downgrade sentence %q", versionSentence)
	}

	bullets := changelogUnreleasedBullets(t)
	var owner string
	for _, b := range bullets {
		if strings.Contains(normalizeProse(b), strings.ToLower(versionSentence)) {
			if owner != "" {
				t.Fatalf("the checkout downgrade sentence must live in exactly one Unreleased bullet")
			}
			owner = normalizeProse(b)
		}
	}
	if owner == "" {
		t.Fatal("no ## Unreleased bullet quotes the checkout downgrade sentence")
	}

	// The version sentence must be attributed to --continue...
	idx := strings.Index(owner, strings.ToLower(versionSentence))
	lead := owner[:idx]
	if !strings.Contains(lead, "--continue") {
		t.Errorf("the checkout downgrade sentence must be attributed to --continue:\n%s", owner)
	}
	// ...and never jointly to a fresh run.
	for _, blurred := range []string{"fresh/--continue", "fresh/`--continue`", "fresh or --continue", "--continue/fresh"} {
		if strings.Contains(owner, blurred) {
			t.Errorf("the checkout downgrade sentence must not be attributed to %q: a fresh run never reaches the version comparison:\n%s", blurred, owner)
		}
	}
	// If the fresh cell is mentioned at all, it must carry its OWN sentence.
	if strings.Contains(owner, "fresh") && !strings.Contains(owner, strings.ToLower(freshSentence)) {
		t.Errorf("a bullet that mentions the fresh checkout cell must quote its own sentence %q:\n%s", freshSentence, owner)
	}
}

// ===========================================================================
// §22.34 — the gate suite is declared, runnable and non-vacuous.
// ===========================================================================

// criterion34GateCommands is §22.34's own list, verbatim: the full gate
// suite, in the spec's order.
var criterion34GateCommands = []string{
	"gofmt -l internal cmd",
	"go test ./... -count=1",
	"go vet ./...",
	"golangci-lint run ./...",
	"make build",
	"git diff --check",
	"tpatch feature deps --validate-all",
}

// criterion34FocusedSelectors is §22.34's "focused gates while implementing"
// block: the -run selectors an implementer is told to use. A selector that
// matches no declared test in the corpus is a documentation lie, so each is
// asserted non-vacuous below.
var criterion34FocusedSelectors = []string{
	"TestRebasePlan|TestPlanFingerprint|TestPlanSchema|TestRemainingRebaseEntries",
	"TestSyncPlan|TestPlanGuard|TestSyncNoFlag_",
	"TestSyncScoped_|TestCheckoutSyncModes_",
}

// declaredTestNames parses every `func TestXxx(` declaration under the two
// packages this feature touches, by scanning the source rather than by
// running anything.
func declaredTestNames(t *testing.T) []string {
	t.Helper()
	re := regexp.MustCompile(`(?m)^func (Test[A-Za-z0-9_]*)\(`)
	var names []string
	for _, dir := range []string{"internal", "internal/cli"} {
		entries, err := os.ReadDir(filepath.Join(docsRepoRoot, dir))
		if err != nil {
			t.Fatalf("read %s: %v", dir, err)
		}
		for _, e := range entries {
			if e.IsDir() || !strings.HasSuffix(e.Name(), "_test.go") {
				continue
			}
			data, err := os.ReadFile(filepath.Join(docsRepoRoot, dir, e.Name()))
			if err != nil {
				t.Fatalf("read %s/%s: %v", dir, e.Name(), err)
			}
			for _, m := range re.FindAllStringSubmatch(string(data), -1) {
				names = append(names, m[1])
			}
		}
	}
	if len(names) == 0 {
		t.Fatal("found no declared test functions at all; the scan is broken")
	}
	return names
}

// TestSyncPlanDocs_Criterion22_34_GateSuiteIsDeclaredAndNonVacuous is
// §22.34's executable owner. The suite itself is run by the outer harness;
// what a test inside the repository can and must own is that every gate the
// criterion names really EXISTS here and that none of its selectors is
// vacuous:
//
//   - `gofmt -l internal cmd` is executed for real and must report nothing;
//   - `make build` names a real Makefile target, and the Makefile also
//     declares the `test` and `lint` targets the suite leans on;
//   - `git diff --check` is executed for real against the working tree;
//   - each focused `-run` selector matches at least one declared test in
//     `internal/` or `internal/cli/`;
//   - the frozen-path gate of criterion 1 still holds: `TestSyncNoFlag_`
//     matches, and the fixture directory still contains exactly 126 files.
//
// A gate command list that drifts from the spec's own block, or a selector
// that stops matching anything, fails here.
func TestSyncPlanDocs_Criterion22_34_GateSuiteIsDeclaredAndNonVacuous(t *testing.T) {
	if len(criterion34GateCommands) != 7 {
		t.Fatalf("§22.34 lists 7 gate commands, this table has %d", len(criterion34GateCommands))
	}

	t.Run("gofmt_reports_nothing", func(t *testing.T) {
		out, err := exec.Command("gofmt", "-l",
			filepath.Join(docsRepoRoot, "internal"), filepath.Join(docsRepoRoot, "cmd")).CombinedOutput()
		if err != nil {
			t.Fatalf("gofmt -l internal cmd: %v\n%s", err, out)
		}
		if strings.TrimSpace(string(out)) != "" {
			t.Fatalf("gofmt -l internal cmd reported unformatted files:\n%s", out)
		}
	})

	t.Run("make_targets_exist", func(t *testing.T) {
		makefile := readRepoDoc(t, "Makefile")
		for _, target := range []string{"build:", "test:", "lint:"} {
			if !regexp.MustCompile(`(?m)^` + regexp.QuoteMeta(target)).MatchString(makefile) {
				t.Fatalf("Makefile declares no %q target, but §22.34's suite invokes it", target)
			}
		}
	})

	t.Run("git_diff_check_is_clean", func(t *testing.T) {
		cmd := exec.Command("git", "diff", "--check")
		cmd.Dir = docsRepoRoot
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git diff --check failed: %v\n%s", err, out)
		}
	})

	t.Run("focused_selectors_are_non_vacuous", func(t *testing.T) {
		names := declaredTestNames(t)
		for _, selector := range criterion34FocusedSelectors {
			re, err := regexp.Compile(selector)
			if err != nil {
				t.Fatalf("selector %q does not compile: %v", selector, err)
			}
			matched := 0
			for _, n := range names {
				if re.MatchString(n) {
					matched++
				}
			}
			if matched == 0 {
				t.Fatalf("focused selector %q matches no declared test: the documented gate is vacuous", selector)
			}
		}
	})

	t.Run("frozen_path_gate_still_holds", func(t *testing.T) {
		names := declaredTestNames(t)
		noflag := 0
		for _, n := range names {
			if strings.HasPrefix(n, "TestSyncNoFlag_") {
				noflag++
			}
		}
		if noflag == 0 {
			t.Fatal("no TestSyncNoFlag_ test is declared; §22 criterion 1's frozen-path gate would be vacuous")
		}
		files := 0
		root := filepath.Join(docsRepoRoot, "internal", "cli", "testdata", "sync_noflag")
		if err := filepath.WalkDir(root, func(_ string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if !d.IsDir() {
				files++
			}
			return nil
		}); err != nil {
			t.Fatalf("walk %s: %v", root, err)
		}
		if files != 126 {
			t.Fatalf("internal/cli/testdata/sync_noflag holds %d files, want the frozen 126", files)
		}
	})
}

// ---------------------------------------------------------------------------
// TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves
// ---------------------------------------------------------------------------

// bannedDocPhrases are the three substrings spec.md §22.33a forbids: an
// unqualified "--plan mutates nothing" claim, a bare `from` scope-value
// spelling, and a ninth warning kind. None of these are flag literals, so
// they are checked separately from TestSyncPlanDocs_FlagWorkflowSurfacesCarryAllFiveLiterals.
var bannedDocPhrases = []string{"without mutating anything", "scope=from", "nine warning"}

// TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves implements spec.md
// §22.33a's negative check exactly as scoped: "exactly two halves, and no
// third". Half (a) is a corpus grep over README.md, CHANGELOG.md, docs/ and
// assets/ only — never internal/, never cmd/, never a _test.go file, never
// a testdata directory — because tests legitimately contain every banned
// phrase as negative fixtures, so an unscoped grep would forbid the very
// tests that enforce this criterion. Half (b) is the exact tws sync --help
// output, asserted never to contain any of the three phrases as a
// substring.
func TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves(t *testing.T) {
	t.Run("prose-and-assets", func(t *testing.T) {
		// This walk is built to match the spec's corpus by construction: it
		// only ever reads README.md, CHANGELOG.md and files under docs/ and
		// assets/, and it skips any directory named "testdata" that it
		// encounters. It never touches internal/, cmd/, or any _test.go
		// file — those simply are not among the four roots below.
		roots := []string{
			filepath.Join(docsRepoRoot, "README.md"),
			filepath.Join(docsRepoRoot, "CHANGELOG.md"),
			filepath.Join(docsRepoRoot, "docs"),
			filepath.Join(docsRepoRoot, "assets"),
		}
		var files []string
		for _, root := range roots {
			info, err := os.Stat(root)
			if err != nil {
				t.Fatalf("stat %s: %v", root, err)
			}
			if !info.IsDir() {
				files = append(files, root)
				continue
			}
			if err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
				if err != nil {
					return err
				}
				if d.IsDir() {
					if d.Name() == "testdata" {
						return filepath.SkipDir
					}
					return nil
				}
				files = append(files, path)
				return nil
			}); err != nil {
				t.Fatalf("walking %s: %v", root, err)
			}
		}
		if len(files) < 5 {
			t.Fatalf("corpus walk found only %d files, expected the README, CHANGELOG and docs/+assets/ trees", len(files))
		}

		for _, path := range files {
			data, err := os.ReadFile(path)
			if err != nil {
				t.Fatalf("reading %s: %v", path, err)
			}
			content := string(data)
			for _, phrase := range bannedDocPhrases {
				if strings.Contains(content, phrase) {
					t.Errorf("%s must not contain the banned phrase %q", path, phrase)
				}
			}
		}

		// Positive control: the Go tree legitimately contains a banned
		// phrase as a negative-fixture string (internal/rebase_plan_render_test.go
		// asserts a rendered Policy line never prints "scope=from"). This
		// file is deliberately outside every root above; if it had been
		// included, this exact check would fail — which is the reason
		// spec.md §22.33a scopes the corpus away from the Go tree at all,
		// rather than an assumption this test takes on faith.
		goFixture := filepath.Join("..", "rebase_plan_render_test.go")
		data, err := os.ReadFile(goFixture)
		if err != nil {
			t.Fatalf("reading %s: %v", goFixture, err)
		}
		if !strings.Contains(string(data), "scope=from") {
			t.Fatalf("%s no longer contains the banned literal \"scope=from\" as a negative-fixture string; the corpus-exclusion rationale (spec.md §22.33a) has nothing left to guard against", goFixture)
		}
	})

	t.Run("help-output", func(t *testing.T) {
		stdout, _, exit := runSyncExecute(t, "--help")
		if exit != 0 {
			t.Fatalf("tws sync --help must exit 0, got %d", exit)
		}
		for _, phrase := range bannedDocPhrases {
			if strings.Contains(stdout, phrase) {
				t.Errorf("tws sync --help must not contain the banned phrase %q:\n%s", phrase, stdout)
			}
		}
	})
}

package internal

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// FeatureRenameCheckpoint is a test-only seam around real, durably intended
// effects. It is never configured through the environment or CLI.
var FeatureRenameCheckpoint func(step, path string) error

// ErrFeatureRenameInterrupted lets tests model process loss without running
// the ordinary-error rollback path. Real process loss leaves the same journal.
var ErrFeatureRenameInterrupted = errors.New("feature rename interrupted")

type FeatureRenameResult struct {
	Path        string
	Journal     string
	Aborted     bool
	CleanupOnly bool
}

// RenameExternalFeature changes no refs, index, working files, or templates.
// The name admission must precede lifecycle/feature mutation/registry locks.
// Recovery reads the bound journal before looking for the old feature path.
func RenameExternalFeature(
	ws Workspace, oldName, newName, recovery string,
	checkSessions func(feature, path string, names []string) error,
	selectedRootSpellings ...string,
) (result FeatureRenameResult, retErr error) {
	if ws.Mode != ModeExternal {
		return result, errors.New("feature rename recovery is external-only")
	}
	if ws.MetadataRoot == "" || ws.RepoRoot == "" {
		return result, errors.New("feature rename requires an explicit workspace and controlling repository")
	}
	rootSpelling := ws.MetadataRoot
	rootBinding, rootAlias, err := resolveFeatureRenameRoot(rootSpelling)
	if err != nil {
		return result, err
	}
	if len(selectedRootSpellings) > 1 {
		return result, errors.New("feature rename requires one execution-selected root")
	}
	if len(selectedRootSpellings) == 1 {
		selected, alias, err := resolveFeatureRenameRoot(selectedRootSpellings[0])
		if err != nil || selected != rootBinding {
			return result, errors.Join(err, errors.New("execution-selected root spelling no longer binds the resolved workspace"))
		}
		rootAlias = alias
	}
	repoBinding, repoAlias, err := resolveFeatureRenameRoot(ws.RepoRoot)
	if err != nil {
		return result, err
	}
	ws.MetadataRoot, ws.RepoRoot = rootBinding.Path, repoBinding.Path
	for _, name := range []string{oldName, newName} {
		if strings.ContainsRune(name, 0) {
			return result, errors.New("feature rename names cannot contain NUL")
		}
		if _, err := ws.ResolveFeaturePath(name); err != nil {
			return result, err
		}
	}
	if oldName == newName {
		return result, errors.New("feature rename requires distinct, non-aliasing names")
	}
	if recovery != "" && recovery != "continue" && recovery != "abort" {
		return result, errors.New("unknown feature rename recovery action")
	}
	if recovery != "" {
		plans, err := featureRenamePendingPlans(ws.MetadataRoot)
		if err != nil {
			return result, err
		}
		matching := false
		for _, plan := range plans {
			if plan.OldName == oldName && plan.NewName == newName {
				matching = true
			}
		}
		if !matching {
			return result, fmt.Errorf("no pending feature rename journal matches %q -> %q in %s (already cleaned or never started)", oldName, newName, ws.MetadataRoot)
		}
	} else {
		for _, name := range []string{oldName, newName} {
			if err := GuardFeatureName(ws.MetadataRoot, name); err != nil {
				return result, err
			}
		}
	}
	admission, err := acquireFeatureRenameAdmissionAt(rootBinding, rootAlias, []string{oldName, newName}, true, true, recovery != "")
	if err != nil {
		return result, err
	}
	defer func() { retErr = errors.Join(retErr, admission.Release()) }()
	if err := featureRenameCheckpoint("after-admission", ws.MetadataRoot); err != nil {
		return result, err
	}
	if err := admission.verify(); err != nil {
		return result, err
	}
	if admission.root != rootBinding {
		return result, errors.New("execution-selected workspace root changed during admission")
	}
	if err := repoAlias.verify(); err != nil {
		return result, err
	}
	pending, err := featureRenamePendingPlans(ws.MetadataRoot)
	if err != nil {
		return result, err
	}
	var tx *featureRenameOperation
	for _, plan := range pending {
		if recovery != "" && plan.OldName == oldName && plan.NewName == newName {
			if tx != nil {
				return result, errors.New("multiple matching feature rename journals; refusing ambiguous recovery")
			}
			tx, err = loadFeatureRename(ws.MetadataRoot, plan.ID)
			if err != nil {
				return result, err
			}
			continue
		}
		if featureRenameNamesAlias(ws.MetadataRoot, plan.OldName, oldName) || featureRenameNamesAlias(ws.MetadataRoot, plan.NewName, oldName) ||
			featureRenameNamesAlias(ws.MetadataRoot, plan.OldName, newName) || featureRenameNamesAlias(ws.MetadataRoot, plan.NewName, newName) ||
			plan.registryChanged() {
			return result, featureRenamePendingError(plan)
		}
	}
	if recovery != "" && tx == nil {
		return result, fmt.Errorf("no pending feature rename journal matches %q -> %q in %s (already cleaned or never started)", oldName, newName, ws.MetadataRoot)
	}
	currentPath := filepath.Join(ws.MetadataRoot, oldName)
	if tx != nil {
		result.Journal = tx.plan.Operation.Path
		if tx.plan.Repository.Path != ws.RepoRoot {
			return result, errors.New("feature rename journal belongs to a different controlling repository")
		}
		if err := tx.plan.Repository.verify(); err != nil {
			return result, err
		}
		currentPath, _, err = tx.location()
		if err != nil {
			return result, err
		}
	}
	lifecycle, err := AcquireManagedFeatureLifecycleLock(currentPath)
	if err != nil {
		return result, err
	}
	defer func() { retErr = errors.Join(retErr, lifecycle.Release()) }()
	featureIdentity, err := featureRenameDirectoryAt(currentPath)
	if err != nil || featureIdentity.Identity != lifecycle.Identity() {
		return result, errors.Join(err, errors.New("feature lifecycle binding changed"))
	}
	lockedInfo, err := lifecycle.dir.Stat()
	if err != nil {
		return result, err
	}
	lockedIdentity, err := managedIdentityFromInfo(lockedInfo)
	if err != nil || lockedIdentity != featureIdentity.Identity {
		return result, errors.Join(err, errors.New("held lifecycle lock does not bind the selected feature inode"))
	}
	if err := featureRenameMutationPreflight(currentPath); err != nil {
		return result, err
	}
	token, err := managedOperationID()
	if err != nil {
		return result, err
	}
	if tx != nil {
		if err := featureRenameRecoveryGuard(currentPath, tx.plan.GuardToken); err != nil {
			return result, err
		}
		token = tx.plan.GuardToken
	}
	if err := ClaimSyncRunGuard(currentPath, token); err != nil {
		return result, fmt.Errorf("claim feature rename mutation reservation: %w", err)
	}
	defer func() {
		// A move or fsync error may have occurred after the directory changed
		// location. Release only at the captured inode's actual public binding.
		path := currentPath
		if tx != nil {
			if actual, locationErr := tx.reservationLocation(); locationErr == nil {
				path = actual
			} else {
				retErr = errors.Join(retErr, fmt.Errorf("mutation reservation retained; feature location is uncertain: %w", locationErr))
				return
			}
		}
		if err := managedVerifyPathIdentity(path, featureIdentity.Identity); err != nil {
			retErr = errors.Join(retErr, err)
			return
		}
		retErr = errors.Join(retErr, ReleaseOwnedSyncRunGuard(path, token))
	}()
	if err := featureRenameMutationPreflight(currentPath); err != nil {
		return result, err
	}
	var registry *SpacesRenameTx
	if tx == nil {
		// Capture before and after the semantic transaction, including identity,
		// so an uncooperative edit during its read cannot change our authority.
		before, err := featureRenameReadFile(SpacesFilePath(ws.MetadataRoot), true)
		if err != nil {
			return result, err
		}
		registry, err = BeginSpacesFeatureRename(ws.MetadataRoot, oldName, newName, currentPath, filepath.Join(ws.MetadataRoot, newName))
		if err != nil {
			return result, err
		}
		defer func() { retErr = errors.Join(retErr, registry.Release()) }()
		if registry.changed && len(pending) > 0 {
			return result, fmt.Errorf("shared registry publication is reserved: %w", featureRenamePendingError(pending[0]))
		}
		if err := before.verifyAt(before.Path); err != nil {
			return result, err
		}
		if _, err := os.Lstat(filepath.Join(ws.MetadataRoot, newName)); !errors.Is(err, fs.ErrNotExist) {
			return result, errors.Join(err, fmt.Errorf("feature destination already exists: %s", newName))
		}
		if present, err := ManagedTemplateStatePresent(currentPath); err != nil {
			return result, err
		} else if present {
			state, err := LoadManagedTemplateState(currentPath)
			if err != nil {
				return result, err
			}
			if err := validateManagedTemplateOwnerForWorkspace(state, ws); err != nil {
				return result, err
			}
		}
		plan, err := buildFeatureRenamePlan(ws, oldName, newName, token, registry, rootAlias, repoAlias)
		if err != nil {
			return result, err
		}
		if err := before.verifyAt(before.Path); err != nil {
			return result, err
		}
		if err := admission.verify(); err != nil {
			return result, err
		}
		if checkSessions != nil {
			if err := checkSessions(oldName, currentPath, plan.names()); err != nil {
				return result, err
			}
		}
		tx, err = newFeatureRenameOperation(plan)
		if err != nil {
			return result, err
		}
		result.Journal = tx.plan.Operation.Path
	} else if tx.plan.Registry.Observation.Exists {
		lock, err := acquireSpacesLock(ws.MetadataRoot)
		if err != nil {
			return result, err
		}
		defer func() { retErr = errors.Join(retErr, lock.Release()) }()
	}
	tx.admission = admission
	tx.checkSession = checkSessions
	if err := tx.syncJournalEvidence(); err != nil {
		return result, tx.failure(err)
	}
	if err := tx.verifyStable(); err != nil {
		return result, tx.failure(err)
	}
	if err := tx.verifyPhysicalInventory(); err != nil {
		return result, tx.failure(err)
	}
	if tx.has("complete", "done") {
		if recovery == "abort" {
			return result, fmt.Errorf("feature rename is durably complete at %s; --abort cannot undo it; use --continue for verified cleanup", result.Journal)
		}
		result.CleanupOnly = true
		err = tx.cleanup(false)
	} else if recovery == "abort" || tx.has("abort", "intent") || tx.has("aborted", "done") {
		err = tx.rollback()
		result.Aborted = true
	} else {
		err = tx.forward()
	}
	if err != nil {
		if recovery == "" && !errors.Is(err, ErrFeatureRenameInterrupted) &&
			!tx.has("complete", "done") && !tx.has("abort", "intent") {
			rollbackErr := tx.rollback()
			if rollbackErr == nil {
				return result, fmt.Errorf("feature rename failed and was rolled back to %s; operation receipt %s: %w",
					tx.plan.Feature.Path, result.Journal, err)
			}
			err = errors.Join(err, fmt.Errorf("automatic rollback could not be proven safe: %w", rollbackErr))
		}
		return result, tx.failure(err)
	}
	result.Path, _, err = tx.location()
	return result, err
}

func featureRenameMutationPreflight(path string) error {
	if err := RefusePendingScopedPush(externalScopedPushLocation(path)); err != nil {
		return err
	}
	if info, err := os.Lstat(SyncRunGuardPath(path)); err == nil {
		if !info.Mode().IsRegular() {
			return errors.New("feature mutation reservation is not a regular file")
		}
	} else if !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	for _, state := range []string{SyncStatePath(path), SyncRunStatePath(path)} {
		if _, err := os.Lstat(state); err == nil {
			return fmt.Errorf("sync recovery evidence at %s blocks feature rename", state)
		} else if !errors.Is(err, fs.ErrNotExist) {
			return err
		}
	}
	if HasReparentState(ReparentLocation{Mode: ModeExternal, Feature: filepath.Base(path), FeaturePath: path}) {
		return fmt.Errorf("stack reparent recovery is active at %s", path)
	}
	if residue, err := ManagedTemplateRecoveryResidue(path); err != nil {
		return err
	} else if residue != "" {
		return fmt.Errorf("managed template recovery is pending at %s", residue)
	}
	return nil
}

func featureRenameRecoveryGuard(path, token string) error {
	info, err := os.Lstat(SyncRunGuardPath(path))
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	if !info.Mode().IsRegular() {
		return errors.New("feature rename mutation reservation is not a regular file")
	}
	guard, err := ReadSyncRunGuard(path)
	if err != nil {
		return err
	}
	if guard.Token != token {
		return errors.New("feature rename refuses a mutation reservation owned by another operation")
	}
	if syncProcessAlive(guard.PID) {
		return fmt.Errorf("feature rename mutation reservation is still live (pid %d)", guard.PID)
	}
	return nil
}

func (plan *featureRenamePlan) names() []string {
	names := make([]string, 0, len(plan.Worktrees))
	for _, tree := range plan.Worktrees {
		names = append(names, tree.Name)
	}
	if len(names) == 0 {
		return []string{"<feature>"}
	}
	return names
}

func (plan *featureRenamePlan) registryChanged() bool {
	return len(plan.Pointers) > 0 && plan.Pointers[len(plan.Pointers)-1].Kind == "registry"
}

func (tx *featureRenameOperation) location() (string, bool, error) {
	if err := tx.plan.Root.verify(); err != nil {
		return "", false, err
	}
	oldPath := tx.plan.Feature.Path
	newPath := filepath.Join(tx.plan.Root.Path, tx.plan.NewName)
	var current string
	moved := false
	for i, path := range []string{oldPath, newPath} {
		info, err := os.Lstat(path)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return "", false, err
		}
		id, err := managedIdentityFromInfo(info)
		if err != nil {
			return "", false, err
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 ||
			id != tx.plan.Feature.Identity || current != "" {
			return "", false, fmt.Errorf("feature rename path was replaced, reoccupied, or aliased at %s; neither occupant will be overwritten", path)
		}
		current, moved = path, i == 1
	}
	if current == "" {
		return "", false, errors.New("neither rename path contains the original feature directory identity")
	}
	return current, moved, nil
}

func (tx *featureRenameOperation) reservationLocation() (string, error) {
	if err := tx.plan.Root.verify(); err != nil {
		return "", err
	}
	current := ""
	for _, path := range []string{tx.plan.Feature.Path, filepath.Join(tx.plan.Root.Path, tx.plan.NewName)} {
		info, err := os.Lstat(path)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return "", err
		}
		id, err := managedIdentityFromInfo(info)
		if err != nil {
			return "", err
		}
		if info.IsDir() && info.Mode()&os.ModeSymlink == 0 && id == tx.plan.Feature.Identity {
			if current != "" {
				return "", errors.New("feature mutation reservation has ambiguous directory bindings")
			}
			current = path
		}
	}
	if current == "" {
		return "", errors.New("feature mutation reservation no longer has a verified public binding")
	}
	return current, nil
}

func (tx *featureRenameOperation) verifyStable() error {
	if err := tx.verifyJournal(); err != nil {
		return err
	}
	for i := range tx.plan.Aliases {
		if err := tx.plan.Aliases[i].verify(); err != nil {
			return err
		}
	}
	path, moved, err := tx.location()
	if err != nil {
		return err
	}
	if err := tx.plan.verifyParents(moved); err != nil {
		return err
	}
	for _, directory := range []featureRenameDirectory{tx.plan.Repository, tx.plan.Common} {
		if err := directory.verify(); err != nil {
			return err
		}
	}
	common, err := tx.plan.common(tx.plan.Repository.Path, false)
	if err != nil || common != tx.plan.Common {
		return errors.Join(err, errors.New("controlling repository common directory changed"))
	}
	if err := featureRenameMutationPreflight(path); err != nil {
		return err
	}
	guard, err := ReadSyncRunGuard(path)
	if err != nil || guard.Token != tx.plan.GuardToken || guard.PID != os.Getpid() {
		return errors.Join(err, errors.New("feature rename mutation reservation changed"))
	}
	for _, file := range tx.plan.Metadata {
		if err := file.verifyAt(filepath.Join(path, filepath.Base(file.Path))); err != nil {
			return err
		}
	}
	if err := tx.verifyOwned(path); err != nil {
		return err
	}
	if !tx.plan.registryChanged() {
		if err := tx.plan.Registry.verifyAt(tx.plan.Registry.Path); err != nil {
			return err
		}
	}
	for i, pointer := range tx.plan.Pointers {
		active, _, _, _, _, err := tx.pointerPaths(i)
		if err != nil {
			return err
		}
		stage := tx.stage(i)
		switch {
		case stage == nil:
			if err := pointer.Before.verifyAt(active); err != nil {
				return err
			}
		case tx.has(fmt.Sprintf("cleanup.%d", i), "intent"):
			expected := pointer.Before.Observation
			if tx.has("complete", "done") {
				expected = *stage.File
			}
			if err := (featureRenameFile{Observation: expected}).verifyAt(active); err != nil {
				return err
			}
		default:
			if _, err := tx.pointerState(i); err != nil {
				return err
			}
		}
	}
	for _, tree := range tx.plan.Worktrees {
		treePath := filepath.Join(path, "worktrees", tree.Name)
		directory := tree.Directory
		directory.Path = treePath
		for _, dir := range []featureRenameDirectory{directory, tree.Repository, tree.Admin, tree.Common} {
			if err := dir.verify(); err != nil {
				return err
			}
		}
		entryCommon, err := tx.plan.common(tree.Repository.Path, false)
		if err != nil || entryCommon != tree.Common {
			return errors.Join(err, fmt.Errorf("selected repository binding changed for %s", tree.Name))
		}
		for _, file := range []featureRenameFile{tree.CommonFile, tree.Head, tree.Index} {
			if err := file.verifyAt(file.Path); err != nil {
				return err
			}
		}
		rewritten := false
		for _, pointer := range tx.plan.Pointers {
			if pointer.Kind == "forward" && pointer.Before.Path == tree.Marker.Path {
				rewritten = true
			}
		}
		if !rewritten {
			if err := tree.Marker.verifyAt(filepath.Join(treePath, ".git")); err != nil {
				return err
			}
		}
		if err := featureRenameIdleGit(tree.Admin.Path); err != nil {
			return err
		}
		if err := featureRenameNoAlternates(tree.Common.Path); err != nil {
			return err
		}
		config, err := featureRenameConfig(tree.Admin.Path)
		if err != nil || digestBytes(config) != tree.ConfigHash {
			return errors.Join(err, fmt.Errorf("Git configuration changed for %s", tree.Name))
		}
		oid, err := featureRenameGit(tree.Admin.Path, "rev-parse", "--verify", "HEAD")
		if err != nil || strings.TrimSuffix(string(oid), "\n") != tree.OID {
			return errors.Join(err, fmt.Errorf("HEAD/ref identity changed for %s", tree.Name))
		}
	}
	if tx.checkSession != nil {
		for _, name := range []string{tx.plan.OldName, tx.plan.NewName} {
			if err := tx.checkSession(name, path, tx.plan.names()); err != nil {
				return err
			}
		}
	}
	return nil
}

func (tx *featureRenameOperation) verifyOwned(path string) error {
	root, err := featureRenameOpenRoot(path)
	if err != nil {
		return err
	}
	defer root.Close() //nolint:errcheck
	for _, expected := range tx.plan.Owned {
		file, err := observeManagedFileRoot(root, expected.Relative)
		if err != nil {
			return err
		}
		link, err := observeManagedLinkRoot(root, expected.Relative)
		if err != nil {
			return err
		}
		if file != expected.File || link != expected.Link {
			return fmt.Errorf("managed ownership/effective content changed at %s", filepath.Join(path, expected.Relative))
		}
	}
	return nil
}

func (tx *featureRenameOperation) failure(cause error) error {
	var completed, pending []string
	for _, event := range tx.events {
		if event.Phase == "done" {
			completed = append(completed, event.Effect)
		} else if !tx.has(event.Effect, "done") {
			pending = append(pending, event.Effect)
		}
	}
	outcome := "feature rename incomplete"
	recovery := "matching --continue or --abort"
	if tx.has("complete", "done") {
		outcome, recovery = "feature rename completed; verified cleanup pending", "matching --continue (abort is no longer allowed)"
	} else if tx.has("aborted", "done") {
		outcome = "feature rename rolled back; verified cleanup pending"
	}
	var private []string
	for _, pointer := range tx.plan.Pointers {
		if _, err := os.Lstat(pointer.StageRoot); err == nil {
			private = append(private, pointer.StageRoot)
		}
	}
	return fmt.Errorf("%s: %w; old=%s new=%s; completed=%q pending=%q; private paths=%q; exact evidence=%s; use %s (never an older tws)",
		outcome,
		cause, tx.plan.Feature.Path, filepath.Join(tx.plan.Root.Path, tx.plan.NewName),
		completed, pending, private, tx.plan.Operation.Path, recovery)
}

func featureRenameCheckpoint(step, path string) error {
	if FeatureRenameCheckpoint != nil {
		return FeatureRenameCheckpoint(step, path)
	}
	return nil
}

func (tx *featureRenameOperation) effect(effect, path string, action func() error) error {
	if tx.has(effect, "done") {
		return action()
	}
	if err := tx.record(effect, "intent", nil); err != nil {
		return err
	}
	if err := featureRenameCheckpoint("before-"+effect, path); err != nil {
		return err
	}
	if err := tx.verifyStable(); err != nil {
		return err
	}
	if err := action(); err != nil {
		return err
	}
	if effect == "complete" || effect == "aborted" {
		// Here the durable record IS the effect and commit point, rather
		// than a progress acknowledgement of an earlier filesystem effect.
		if err := tx.record(effect, "done", nil); err != nil {
			return err
		}
		return featureRenameCheckpoint("after-"+effect, path)
	}
	if err := featureRenameCheckpoint("after-"+effect, path); err != nil {
		return err
	}
	return tx.record(effect, "done", nil)
}

func (tx *featureRenameOperation) forward() error {
	for i := range tx.plan.Pointers {
		if err := tx.preparePointer(i); err != nil {
			return err
		}
	}
	if err := tx.effect("move", tx.plan.Feature.Path, func() error { return tx.move(false) }); err != nil {
		return err
	}
	for i, pointer := range tx.plan.Pointers {
		if pointer.Kind == "registry" {
			if err := tx.verifyFinalGit(true); err != nil {
				return err
			}
			if !tx.has(fmt.Sprintf("preserve.%d", i), "intent") && SpacesSaveHook != nil {
				if err := SpacesSaveHook(tx.plan.Root.Path); err != nil {
					return err
				}
			}
		}
		if err := tx.effect(fmt.Sprintf("preserve.%d", i), pointer.Before.Path, func() error {
			return tx.preservePointer(i)
		}); err != nil {
			return err
		}
		if err := tx.effect(fmt.Sprintf("publish.%d", i), pointer.Before.Path, func() error {
			return tx.publishPointer(i)
		}); err != nil {
			return err
		}
	}
	if err := tx.verifyFinal(true); err != nil {
		return err
	}
	if err := tx.effect("complete", tx.plan.Operation.Path, func() error { return tx.verifyFinal(true) }); err != nil {
		return err
	}
	return tx.cleanup(false)
}

func (tx *featureRenameOperation) move(back bool) error {
	if err := tx.verifyStable(); err != nil {
		return err
	}
	if err := tx.verifyPhysicalInventory(); err != nil {
		return err
	}
	_, moved, err := tx.location()
	if err != nil {
		return err
	}
	if moved != back {
		return featureRenameSyncDirectory(tx.plan.Root)
	}
	if back && tx.plan.registryChanged() {
		if err := tx.plan.Registry.verifyAt(tx.plan.Registry.Path); err != nil {
			return fmt.Errorf("registry must be restored before moving the feature back: %w", err)
		}
	}
	from, to := tx.plan.OldName, tx.plan.NewName
	if back {
		from, to = to, from
	}
	if err := featureRenameCheckpoint("before-move-publication", filepath.Join(tx.plan.Root.Path, to)); err != nil {
		return err
	}
	if err := tx.plan.verifyParents(moved); err != nil {
		return err
	}
	return featureRenameRenameNoReplace(tx.plan.Root, from, to)
}

func (tx *featureRenameOperation) pointerPaths(index int) (active, original, next, published string, root featureRenameDirectory, err error) {
	pointer := tx.plan.Pointers[index]
	root = tx.plan.Root
	active = pointer.Before.Path
	switch pointer.Kind {
	case "backpointer":
		root = tx.plan.Worktrees[pointer.Worktree].Admin
	case "forward":
		path, _, locationErr := tx.location()
		if locationErr != nil {
			err = locationErr
			return
		}
		active = filepath.Join(path, "worktrees", tx.plan.Worktrees[pointer.Worktree].Name, ".git")
	}
	original = filepath.Join(pointer.StageRoot, "original")
	next = filepath.Join(pointer.StageRoot, "next")
	published = filepath.Join(pointer.StageRoot, "published")
	return
}

func (tx *featureRenameOperation) preparePointer(index int) error {
	pointer := tx.plan.Pointers[index]
	if stage := tx.stage(index); stage != nil {
		if err := stage.Directory.verify(); err != nil {
			return err
		}
		if err := (featureRenameFile{Observation: *stage.File}).verifyAt(filepath.Join(pointer.StageRoot, "next")); err != nil {
			return err
		}
		return featureRenameSyncDirectory(*stage.Directory)
	}
	effect := fmt.Sprintf("stage.%d", index)
	if err := tx.record(effect, "intent", nil); err != nil {
		return err
	}
	if err := tx.verifyStable(); err != nil {
		return err
	}
	_, _, _, _, binding, err := tx.pointerPaths(index)
	if err != nil {
		return err
	}
	parent, err := featureRenamePinnedRoot(binding)
	if err != nil {
		return err
	}
	defer parent.Close() //nolint:errcheck
	if err := parent.Mkdir(filepath.Base(pointer.StageRoot), 0o700); err != nil {
		return fmt.Errorf("unknown or incomplete staging at %s; it will not be overwritten: %w", pointer.StageRoot, err)
	}
	if err := managedSyncRootDir(parent, "."); err != nil {
		return err
	}
	directory, err := featureRenameDirectoryAt(pointer.StageRoot)
	if err != nil {
		return err
	}
	if err := featureRenameWriteExclusive(directory, "next", pointer.After, fs.FileMode(pointer.Before.Observation.Mode)); err != nil {
		return err
	}
	file, err := featureRenameReadFile(filepath.Join(pointer.StageRoot, "next"), false)
	if err != nil {
		return err
	}
	return tx.record(effect, "done", &featureRenameEvent{Directory: &directory, File: &file.Observation})
}

func (tx *featureRenameOperation) renamePointerObject(index int, from, to string, expected managedFileObservation) error {
	_, _, _, _, binding, err := tx.pointerPaths(index)
	if err != nil {
		return err
	}
	if err := binding.verify(); err != nil {
		return err
	}
	if err := (featureRenameFile{Observation: expected}).verifyAt(from); err != nil {
		return err
	}
	fromName, err := filepath.Rel(binding.Path, from)
	if err != nil {
		return err
	}
	toName, err := filepath.Rel(binding.Path, to)
	if err != nil {
		return err
	}
	if err := featureRenameCheckpoint(fmt.Sprintf("before-pointer-capture.%d", index), from); err != nil {
		return err
	}
	if err := tx.verifyStable(); err != nil {
		return err
	}
	renameErr := featureRenameRenameNoReplace(binding, fromName, toName)
	// Verify the captured object even when the rename returned a sync error.
	// An unexpected object is preserved, never discarded or overwritten.
	checkErr := (featureRenameFile{Observation: expected}).verifyAt(to)
	return errors.Join(renameErr, checkErr)
}

func (tx *featureRenameOperation) pointerState(index int) (string, error) {
	active, original, next, published, _, err := tx.pointerPaths(index)
	if err != nil {
		return "", err
	}
	pointer := tx.plan.Pointers[index]
	stage := tx.stage(index)
	if stage == nil {
		return "", fmt.Errorf("no verified staging evidence for %s", active)
	}
	if err := stage.Directory.verify(); err != nil {
		return "", err
	}
	if err := (featureRenameFile{Observation: *stage.File}).verifyAt(next); err != nil {
		return "", err
	}
	live, err := featureRenameReadFile(active, false)
	if err != nil {
		return "", err
	}
	saved, err := featureRenameReadFile(original, false)
	if err != nil {
		return "", err
	}
	retired, err := featureRenameReadFile(published, false)
	if err != nil {
		return "", err
	}
	pre, post := pointer.Before.Observation, *stage.File
	switch {
	case live.Observation == pre && !saved.Observation.Exists &&
		(!retired.Observation.Exists || retired.Observation == post):
		return "original", nil
	case !live.Observation.Exists && saved.Observation == pre &&
		(!retired.Observation.Exists || retired.Observation == post):
		return "preserved", nil
	case live.Observation == post && saved.Observation == pre && !retired.Observation.Exists:
		return "published", nil
	default:
		return "", fmt.Errorf("unknown pointer/registry binding at %s; preserve evidence at %s", active, pointer.StageRoot)
	}
}

func (tx *featureRenameOperation) preservePointer(index int) error {
	state, err := tx.pointerState(index)
	if err != nil {
		return err
	}
	if state != "original" {
		return tx.syncPointerBindings(index, state)
	}
	if tx.has(fmt.Sprintf("preserve.%d", index), "done") {
		return errors.New("preserved pointer unexpectedly returned to its original binding")
	}
	active, original, _, _, _, err := tx.pointerPaths(index)
	if err != nil {
		return err
	}
	return tx.renamePointerObject(index, active, original, tx.plan.Pointers[index].Before.Observation)
}

func (tx *featureRenameOperation) publishPointer(index int) error {
	state, err := tx.pointerState(index)
	if err != nil {
		return err
	}
	if state == "published" {
		return tx.syncPointerBindings(index, state)
	}
	if state != "preserved" || tx.has(fmt.Sprintf("publish.%d", index), "done") {
		return errors.New("pointer publication lost its preserved original or owned postimage")
	}
	active, _, next, _, binding, err := tx.pointerPaths(index)
	if err != nil {
		return err
	}
	root, err := featureRenamePinnedRoot(binding)
	if err != nil {
		return err
	}
	defer root.Close() //nolint:errcheck
	activeRel, err := filepath.Rel(binding.Path, active)
	if err != nil {
		return err
	}
	nextRel, err := filepath.Rel(binding.Path, next)
	if err != nil {
		return err
	}
	source, sourceID, err := managedOpenPinnedDirectory(root, filepath.Dir(nextRel), false)
	if err != nil {
		return err
	}
	defer source.Close() //nolint:errcheck
	if sourceID != tx.stage(index).Directory.Identity {
		return errors.New("pointer staging parent identity changed")
	}
	destination, destinationID, err := managedOpenPinnedDirectory(root, filepath.Dir(activeRel), false)
	if err != nil {
		return err
	}
	defer destination.Close() //nolint:errcheck
	expectedDestination := binding.Identity
	if tx.plan.Pointers[index].Kind == "forward" {
		expectedDestination = tx.plan.Worktrees[tx.plan.Pointers[index].Worktree].Directory.Identity
	}
	if destinationID != expectedDestination {
		return errors.New("pointer destination parent identity changed")
	}
	if err := featureRenameCheckpoint(fmt.Sprintf("before-pointer-publication.%d", index), active); err != nil {
		return err
	}
	if err := binding.verify(); err != nil {
		return err
	}
	if err := managedVerifyPinnedDirectoryBinding(root, filepath.Dir(activeRel), destinationID); err != nil {
		return err
	}
	if err := managedLinkPinned(source, filepath.Base(nextRel), destination, filepath.Base(activeRel)); err != nil {
		return err
	}
	if err := featureRenameCheckpoint(fmt.Sprintf("after-pointer-link-before-sync.%d", index), active); err != nil {
		return err
	}
	return errors.Join(
		featureRenameSyncDirectory(featureRenameDirectory{Path: filepath.Dir(active), Identity: destinationID}),
		managedVerifyPinnedDirectoryBinding(root, filepath.Dir(nextRel), sourceID),
		managedVerifyPinnedDirectoryBinding(root, filepath.Dir(activeRel), destinationID),
		(featureRenameFile{Observation: *tx.stage(index).File}).verifyAt(active),
	)
}

func (tx *featureRenameOperation) verifyFinalGit(moved bool) error {
	if err := tx.verifyStable(); err != nil {
		return err
	}
	if err := tx.verifyPhysicalInventory(); err != nil {
		return err
	}
	path, actualMoved, err := tx.location()
	if err != nil || actualMoved != moved {
		return errors.Join(err, errors.New("feature rename is not at the required final binding"))
	}
	for _, tree := range tx.plan.Worktrees {
		treePath := filepath.Join(path, "worktrees", tree.Name)
		if err := verifyInjectWorktree(path, treePath); err != nil {
			return err
		}
		admin, err := resolveInjectGitDir(treePath, filepath.Join(treePath, ".git"))
		if err != nil || featureRenameMappedPath(admin, tx.plan.Aliases) != tree.Admin.Path {
			return errors.Join(err, errors.New("final worktree admin binding changed"))
		}
		actualAdmin, err := featureRenameGitPath(treePath, "rev-parse", "--absolute-git-dir")
		if err != nil || featureRenameMappedPath(actualAdmin, tx.plan.Aliases) != tree.Admin.Path {
			return errors.Join(err, errors.New("Git reports a different final administrative directory"))
		}
		common, err := tx.plan.common(treePath, false)
		if err != nil || common != tree.Common {
			return errors.Join(err, errors.New("final worktree common directory changed"))
		}
	}
	return tx.plan.verifyInventory(moved)
}

func (tx *featureRenameOperation) verifyPhysicalInventory() error {
	path, _, err := tx.location()
	if err != nil {
		return err
	}
	physical, err := featureRenameScanGit(path)
	if err != nil {
		return err
	}
	found := make(map[string]bool, len(physical))
	for _, root := range physical {
		found[root] = true
	}
	for i, tree := range tx.plan.Worktrees {
		expected := filepath.Join(path, "worktrees", tree.Name)
		if !found[expected] {
			// A recorded forward-pointer preservation can legitimately leave
			// this one marker absent until publication or restoration.
			for index, pointer := range tx.plan.Pointers {
				if pointer.Kind == "forward" && pointer.Worktree == i &&
					tx.has(fmt.Sprintf("preserve.%d", index), "intent") {
					state, stateErr := tx.pointerState(index)
					if stateErr != nil {
						return stateErr
					}
					if state == "preserved" {
						found[expected] = true
					}
				}
			}
		}
		if !found[expected] {
			return errors.New("physical Git inventory no longer matches the frozen rename plan")
		}
	}
	if len(found) != len(tx.plan.Worktrees) {
		return errors.New("physical Git inventory changed since feature rename planning")
	}
	return nil
}

func (tx *featureRenameOperation) verifyFinal(moved bool) error {
	if err := tx.verifyFinalGit(moved); err != nil {
		return err
	}
	if !moved || !tx.plan.registryChanged() {
		if err := tx.plan.Registry.verifyAt(tx.plan.Registry.Path); err != nil {
			return err
		}
	}
	for i, pointer := range tx.plan.Pointers {
		active, _, _, _, _, err := tx.pointerPaths(i)
		if err != nil {
			return err
		}
		expected := pointer.Before.Observation
		if moved {
			stage := tx.stage(i)
			if stage == nil {
				return errors.New("final pointer has no staging evidence")
			}
			expected = *stage.File
		}
		if err := (featureRenameFile{Observation: expected}).verifyAt(active); err != nil {
			return err
		}
	}
	return nil
}

func (tx *featureRenameOperation) rollback() error {
	if tx.has("complete", "done") {
		return errors.New("completed feature rename cannot be aborted")
	}
	if tx.has("aborted", "done") {
		return tx.cleanup(true)
	}
	if err := tx.verifyStable(); err != nil {
		return err
	}
	if err := tx.verifyPhysicalInventory(); err != nil {
		return err
	}
	// Judge the entire inverse before changing anything. In particular a
	// foreign registry edit must not cause a directory-only rollback.
	if !tx.plan.registryChanged() {
		if err := tx.plan.Registry.verifyAt(tx.plan.Registry.Path); err != nil {
			return err
		}
	}
	for i, pointer := range tx.plan.Pointers {
		if tx.stage(i) == nil {
			if _, err := os.Lstat(pointer.StageRoot); !errors.Is(err, fs.ErrNotExist) {
				return errors.Join(err, fmt.Errorf("unknown staging residue at %s", pointer.StageRoot))
			}
			active, _, _, _, _, err := tx.pointerPaths(i)
			if err != nil {
				return err
			}
			if err := pointer.Before.verifyAt(active); err != nil {
				return err
			}
		} else if _, err := tx.pointerState(i); err != nil {
			return err
		}
	}
	if err := tx.record("abort", "intent", nil); err != nil {
		return err
	}
	if err := tx.record("abort", "done", nil); err != nil {
		return err
	}
	for i := len(tx.plan.Pointers) - 1; i >= 0; i-- {
		if tx.stage(i) == nil {
			continue
		}
		pointer := tx.plan.Pointers[i]
		if err := tx.effect(fmt.Sprintf("unpublish.%d", i), pointer.Before.Path, func() error {
			state, err := tx.pointerState(i)
			if err != nil {
				return err
			}
			if state != "published" {
				return tx.syncPointerBindings(i, state)
			}
			active, _, _, retired, _, err := tx.pointerPaths(i)
			if err != nil {
				return err
			}
			return tx.renamePointerObject(i, active, retired, *tx.stage(i).File)
		}); err != nil {
			return err
		}
		if err := tx.effect(fmt.Sprintf("restore.%d", i), pointer.Before.Path, func() error {
			state, err := tx.pointerState(i)
			if err != nil {
				return err
			}
			if state == "original" {
				return tx.syncPointerBindings(i, state)
			}
			if state != "preserved" {
				return errors.New("owned publication must be preserved before restoring the original")
			}
			active, original, _, _, _, err := tx.pointerPaths(i)
			if err != nil {
				return err
			}
			return tx.renamePointerObject(i, original, active, pointer.Before.Observation)
		}); err != nil {
			return err
		}
	}
	if err := tx.effect("move-back", tx.plan.Feature.Path, func() error { return tx.move(true) }); err != nil {
		return err
	}
	if err := tx.effect("aborted", tx.plan.Operation.Path, func() error { return tx.verifyFinal(false) }); err != nil {
		return err
	}
	return tx.cleanup(true)
}

func (tx *featureRenameOperation) cleanup(aborted bool) error {
	if err := tx.verifyFinal(!aborted); err != nil {
		return err
	}
	if err := tx.syncFinalDirectories(); err != nil {
		return err
	}
	if err := tx.verifyFinal(!aborted); err != nil {
		return err
	}
	for i, pointer := range tx.plan.Pointers {
		if tx.stage(i) == nil {
			continue
		}
		if err := tx.effect(fmt.Sprintf("cleanup.%d", i), pointer.StageRoot, func() error {
			return tx.cleanupPointer(i, aborted)
		}); err != nil {
			return err
		}
	}
	return tx.effect("cleaned", tx.plan.Operation.Path, func() error { return tx.verifyFinal(!aborted) })
}

func (tx *featureRenameOperation) cleanupPointer(index int, aborted bool) error {
	stage := tx.stage(index)
	info, err := os.Lstat(stage.Directory.Path)
	if errors.Is(err, fs.ErrNotExist) && tx.has(fmt.Sprintf("cleanup.%d", index), "intent") {
		_, _, _, _, binding, err := tx.pointerPaths(index)
		if err != nil {
			return err
		}
		if err := tx.verifyStable(); err != nil {
			return err
		}
		if err := featureRenameSyncDirectory(binding); err != nil {
			return err
		}
		if _, err := os.Lstat(stage.Directory.Path); !errors.Is(err, fs.ErrNotExist) {
			return errors.Join(err, errors.New("cleanup directory reappeared during durability barrier"))
		}
		return nil
	}
	if err != nil {
		return err
	}
	id, err := managedIdentityFromInfo(info)
	if err != nil || id != stage.Directory.Identity {
		return errors.Join(err, errors.New("cleanup staging directory was replaced"))
	}
	root, err := featureRenamePinnedRoot(*stage.Directory)
	if err != nil {
		return err
	}
	defer root.Close() //nolint:errcheck
	expected := map[string]managedFileObservation{
		"next": *stage.File, "original": tx.plan.Pointers[index].Before.Observation,
		"published": *stage.File,
	}
	entries, err := fs.ReadDir(root.FS(), ".")
	if err != nil {
		return err
	}
	for _, entry := range entries {
		name := strings.TrimPrefix(entry.Name(), "cleanup-")
		want, known := expected[name]
		if !known || (aborted && name == "original") ||
			(name == "published" && !tx.has(fmt.Sprintf("unpublish.%d", index), "intent")) {
			return fmt.Errorf("unexpected recovery residue at %s; it will not be removed", filepath.Join(stage.Directory.Path, entry.Name()))
		}
		got, err := observeManagedFileRoot(root, entry.Name())
		if err != nil || got != want {
			return errors.Join(err, fmt.Errorf("recovery object changed at %s", filepath.Join(stage.Directory.Path, entry.Name())))
		}
	}
	for _, name := range []string{"original", "published", "next"} {
		private := "cleanup-" + name
		original, err := observeManagedFileRoot(root, name)
		if err != nil {
			return err
		}
		if original.Exists {
			if err := featureRenameCheckpoint(fmt.Sprintf("before-cleanup-capture.%d.%s", index, name), filepath.Join(stage.Directory.Path, name)); err != nil {
				return err
			}
			if err := stage.Directory.verify(); err != nil {
				return err
			}
			if err := tx.verifyStable(); err != nil {
				return err
			}
			if err := featureRenameRenameNoReplace(*stage.Directory, name, private); err != nil {
				return err
			}
			if err := featureRenameCheckpoint(fmt.Sprintf("after-cleanup-capture.%d.%s", index, name), filepath.Join(stage.Directory.Path, private)); err != nil {
				return err
			}
		}
		captured, err := observeManagedFileRoot(root, private)
		if err != nil {
			return err
		}
		if !captured.Exists {
			if err := featureRenameSyncDirectory(*stage.Directory); err != nil {
				return err
			}
			continue
		}
		if captured != expected[name] {
			return fmt.Errorf("unexpected object captured at %s; preserving it", filepath.Join(stage.Directory.Path, private))
		}
		if err := featureRenameCheckpoint(fmt.Sprintf("before-cleanup-remove.%d.%s", index, name), filepath.Join(stage.Directory.Path, private)); err != nil {
			return err
		}
		if err := stage.Directory.verify(); err != nil {
			return err
		}
		if err := tx.verifyStable(); err != nil {
			return err
		}
		if got, err := observeManagedFileRoot(root, private); err != nil || got != expected[name] {
			return errors.Join(err, errors.New("cleanup object changed immediately before removal"))
		}
		if err := root.Remove(private); err != nil {
			return err
		}
		if err := featureRenameCheckpoint("after-cleanup-remove-before-sync", filepath.Join(stage.Directory.Path, private)); err != nil {
			return err
		}
		if err := featureRenameSyncDirectory(*stage.Directory); err != nil {
			return err
		}
		if err := featureRenameCheckpoint(fmt.Sprintf("after-cleanup-remove.%d.%s", index, name), filepath.Join(stage.Directory.Path, private)); err != nil {
			return err
		}
	}
	_, _, _, _, binding, err := tx.pointerPaths(index)
	if err != nil {
		return err
	}
	parent, err := featureRenamePinnedRoot(binding)
	if err != nil {
		return err
	}
	defer parent.Close() //nolint:errcheck
	if err := stage.Directory.verify(); err != nil {
		return err
	}
	if err := parent.Remove(filepath.Base(stage.Directory.Path)); err != nil {
		return err
	}
	if err := featureRenameCheckpoint("after-cleanup-directory-remove-before-sync", stage.Directory.Path); err != nil {
		return err
	}
	return featureRenameSyncDirectory(binding)
}

package internal

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
)

// MigrateResult describes the outcome of a migration run.
type MigrateResult struct {
	Migrated []string // features successfully moved
	Skipped  []string // features already in new layout
	Errors   []string // rollback/failure messages
}

// MigrateFeatureLayout migrates a single feature from legacy (.tws/<name>)
// to new layout (.tws/features/<name>). Returns an error if:
//   - feature name is invalid/unsafe
//   - the name or the directory is claimed by a registered sibling space
//   - source is a symlink
//   - destination already exists (collision)
//   - move fails
func MigrateFeatureLayout(ws Workspace, feature string) (err error) {
	if err := validateFeatureName(feature); err != nil {
		return err
	}

	src := filepath.Join(ws.MetadataRoot, feature)
	dst := filepath.Join(ws.MetadataRoot, "features", feature)

	// Refuse to move a directory whose name is owned by a registered sibling
	// space, or that still contains a registered target, before any
	// filesystem work. The transaction also refuses a destination name owned
	// by a features/<name> space, which the collision check below cannot see,
	// and it holds the spaces lock across os.Rename so no concurrent
	// `tws space add` can register into the directory being moved.
	tx, err := BeginSpacesLayoutMigration(ws.MetadataRoot,
		[]LayoutMigrationTarget{{Feature: feature, Path: src}})
	if err != nil {
		return err
	}
	defer func() {
		err = errors.Join(err, tx.Release())
	}()

	// Reject symlinks at source.
	info, statErr := os.Lstat(src)
	if statErr != nil {
		return fmt.Errorf("source %s does not exist: %w", src, statErr)
	}
	if info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("source %s is a symlink; refusing to migrate", src)
	}
	if !info.IsDir() {
		return fmt.Errorf("source %s is not a directory", src)
	}

	// Check destination collision.
	if _, dstErr := os.Lstat(dst); dstErr == nil {
		return fmt.Errorf("destination %s already exists (collision)", dst)
	} else if !errors.Is(dstErr, os.ErrNotExist) {
		return dstErr
	}

	lifecycle, err := AcquireManagedFeatureLifecycleLock(src)
	if err != nil {
		return err
	}
	defer func() { err = errors.Join(err, lifecycle.Release()) }()
	reservation, err := AcquireCheckoutMetadataReservation(ws, feature)
	if err != nil {
		return err
	}
	defer func() { err = errors.Join(err, reservation.Release()) }()
	if err := scopedPushCheckpoint("after-checkout-metadata-guard", 0); err != nil {
		return err
	}
	if err := reservation.ValidatePublicationReceipt(feature, src); err != nil {
		return err
	}
	if err := reservation.EnsureFeatureParent(); err != nil {
		return err
	}
	if err := reservation.RetirePublicationReceipt(feature, src); err != nil {
		return err
	}
	moved, moveErr := reservation.MoveFeature(src, dst, lifecycle.Identity())
	if moveErr != nil {
		var compensateErr error
		if moved {
			_, compensateErr = reservation.MoveFeature(dst, src, lifecycle.Identity())
		}
		return errors.Join(moveErr, compensateErr)
	}
	return reservation.CommitMoves()
}

// MigrateAllFeatures migrates all legacy features to the new layout.
// Preflight: one spaces transaction for the whole batch, then all sources and
// destinations, before moving any.
// On failure mid-run: rollback every item known to have moved, including the
// failing item when its directory syscall preceded a durability error.
func MigrateAllFeatures(ws Workspace) (result MigrateResult) {
	if ws.Mode != ModeCheckout {
		result.Errors = append(result.Errors, "migrate-layout requires checkout mode")
		return result
	}

	// Discover legacy candidates (dirs in MetadataRoot that are not reserved).
	// Discovery is read-only, so it may precede the spaces preflight; nothing
	// is created or moved until the whole batch has been cleared.
	entries, err := os.ReadDir(ws.MetadataRoot)
	if err != nil {
		result.Errors = append(result.Errors, fmt.Sprintf("reading %s: %v", ws.MetadataRoot, err))
		return result
	}

	var candidates []string
	for _, e := range entries {
		if !e.IsDir() || isReservedDir(e.Name()) {
			continue
		}
		candidates = append(candidates, e.Name())
	}
	sort.Strings(candidates)

	// Fail-closed spaces preflight, executed exactly once for the whole batch
	// and always before `features/` is created or anything is moved. A
	// registered name, or a registered target inside any candidate, is an
	// error and never a skip: one registration blocks every candidate rather
	// than producing a partial run.
	targets := make([]LayoutMigrationTarget, 0, len(candidates))
	for _, name := range candidates {
		targets = append(targets, LayoutMigrationTarget{
			Feature: name,
			Path:    filepath.Join(ws.MetadataRoot, name),
		})
	}
	tx, txErr := BeginSpacesLayoutMigration(ws.MetadataRoot, targets)
	if txErr != nil {
		result.Errors = append(result.Errors, txErr.Error())
		return result
	}
	// The lock is held across every move and any rollback below.
	defer func() {
		if relErr := tx.Release(); relErr != nil {
			result.Errors = append(result.Errors, relErr.Error())
		}
	}()

	if len(candidates) == 0 {
		return result
	}

	// --- Preflight: check all sources and destinations ---
	type migration struct {
		name      string
		src       string
		dst       string
		lifecycle *ManagedFeatureLifecycleLock
	}
	var migrations []migration

	for _, name := range candidates {
		src := filepath.Join(ws.MetadataRoot, name)
		dst := filepath.Join(ws.MetadataRoot, "features", name)

		// Reject symlinks.
		info, err := os.Lstat(src)
		if err != nil {
			result.Errors = append(result.Errors, fmt.Sprintf("stat %s: %v", src, err))
			continue
		}
		if info.Mode()&os.ModeSymlink != 0 {
			result.Errors = append(result.Errors, fmt.Sprintf("%s is a symlink; skipped", src))
			continue
		}

		// Check if already migrated (exists under features/).
		if _, err := os.Lstat(dst); err == nil {
			result.Skipped = append(result.Skipped, name)
			continue
		} else if !errors.Is(err, os.ErrNotExist) {
			result.Errors = append(result.Errors, err.Error())
			continue
		}

		migrations = append(migrations, migration{name: name, src: src, dst: dst})
	}

	// If any preflight errors detected, abort without moving anything.
	if len(result.Errors) > 0 {
		return result
	}

	for i := range migrations {
		lock, err := AcquireManagedFeatureLifecycleLock(migrations[i].src)
		if err != nil {
			result.Errors = append(result.Errors, err.Error())
			return result
		}
		migrations[i].lifecycle = lock
		defer func() {
			if err := lock.Release(); err != nil {
				result.Errors = append(result.Errors, err.Error())
			}
		}()
	}
	reservation, err := AcquireCheckoutMetadataReservation(ws, "layout-migration")
	if err != nil {
		result.Errors = append(result.Errors, err.Error())
		return result
	}
	defer func() {
		if err := reservation.Release(); err != nil {
			result.Errors = append(result.Errors, err.Error())
		}
	}()
	if err := scopedPushCheckpoint("after-checkout-metadata-guard", 0); err != nil {
		result.Errors = append(result.Errors, err.Error())
		return result
	}
	for _, m := range migrations {
		if err := reservation.ValidatePublicationReceipt(m.name, m.src); err != nil {
			result.Errors = append(result.Errors, err.Error())
			return result
		}
	}
	if err := reservation.EnsureFeatureParent(); err != nil {
		result.Errors = append(result.Errors, err.Error())
		return result
	}
	for _, m := range migrations {
		if err := reservation.RetirePublicationReceipt(m.name, m.src); err != nil {
			result.Errors = append(result.Errors, err.Error())
			return result
		}
	}

	// --- Execute moves with rollback on failure ---
	var moved []migration
	for _, m := range migrations {
		currentMoved, err := reservation.MoveFeature(m.src, m.dst, m.lifecycle.Identity())
		if err != nil {
			result.Errors = append(result.Errors, fmt.Sprintf("moving %s: %v", m.name, err))
			if currentMoved {
				moved = append(moved, m)
			}
			// Best-effort rollback.
			for i := len(moved) - 1; i >= 0; i-- {
				done := moved[i]
				if _, rbErr := reservation.MoveFeature(done.dst, done.src, done.lifecycle.Identity()); rbErr != nil {
					result.Errors = append(result.Errors, fmt.Sprintf("rollback %s failed: %v", done.name, rbErr))
				}
			}
			return result
		}
		moved = append(moved, m)
		result.Migrated = append(result.Migrated, m.name)
	}
	if err := reservation.CommitMoves(); err != nil {
		result.Errors = append(result.Errors, err.Error())
	}

	return result
}

package internal

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"

	"gopkg.in/yaml.v3"
)

// ============================================================================
// The pending remote follow-up record (§12) — core.
//
// This feature makes ZERO provider calls, never pushes, and never touches
// upstream configuration. What it does do is leave a local, versioned record
// saying "these branches were rewritten and their pull requests still point
// at the old base", so the next push can warn and strengthen its lease.
//
// This file owns the record, its durable IO, the §12.2 guidance, the §12.5
// clearing observations and the pure decision/preflight values rule R-PUSH
// consumes. It deliberately wires NOTHING into the shipped push paths: that
// integration is a later slice, and a record type that exists before the
// executor is exactly what stage `writing-remote-record` depends on.
// ============================================================================

// ReparentRemoteRecordVersion is the record's schema version. A greater value
// refuses reparent-state-unsupported, exactly as the state artifact does.
const ReparentRemoteRecordVersion = 1

// The two entry states of §12.3.
const (
	ReparentRemoteStatePending = "pending"
	ReparentRemoteStateCleared = "cleared"
)

// ReparentRemoteEntry is one recorded branch. remote is the constant "origin"
// because that is the only remote all three live push paths name.
type ReparentRemoteEntry struct {
	Name      string `yaml:"name"`
	GitBranch string `yaml:"git_branch"`
	Repo      string `yaml:"repo,omitempty"`
	Remote    string `yaml:"remote"`
	RemoteRef string `yaml:"remote_ref"`

	NewTipSHA        string `yaml:"new_tip_sha"`
	RemoteSHAAtWrite string `yaml:"remote_sha_at_write"`

	PRBaseBefore string `yaml:"pr_base_before"`
	PRBaseAfter  string `yaml:"pr_base_after"`

	State string `yaml:"state"`
}

// Pending reports whether this entry still constrains a push.
func (e ReparentRemoteEntry) Pending() bool { return e.State == ReparentRemoteStatePending }

// Published reports whether a remote branch was actually observed when the
// entry was written. An unpublished entry is written cleared, so a later bare
// lease against a concurrently appearing ref stays safe without this record
// having to guess.
func (e ReparentRemoteEntry) Published() bool { return strings.TrimSpace(e.RemoteSHAAtWrite) != "" }

// ReparentRemoteRecord is the whole file.
type ReparentRemoteRecord struct {
	RecordVersion int                   `yaml:"record_version"`
	Feature       string                `yaml:"feature"`
	RunID         string                `yaml:"run_id"`
	CreatedAt     string                `yaml:"created_at"`
	Entries       []ReparentRemoteEntry `yaml:"entries"`
}

// PendingEntries returns the still-pending entry names, in record order.
func (r ReparentRemoteRecord) PendingEntries() []string {
	var out []string
	for _, e := range r.Entries {
		if e.Pending() {
			out = append(out, e.Name)
		}
	}
	return out
}

// Entry finds one entry by logical name.
func (r ReparentRemoteRecord) Entry(name string) (ReparentRemoteEntry, bool) {
	for _, e := range r.Entries {
		if e.Name == name {
			return e, true
		}
	}
	return ReparentRemoteEntry{}, false
}

// AllCleared reports whether every entry is cleared — the condition under
// which the file itself must be deleted.
func (r ReparentRemoteRecord) AllCleared() bool {
	for _, e := range r.Entries {
		if e.Pending() {
			return false
		}
	}
	return true
}

// reparentRemoteInitialState is §12.3's initial-state rule: an entry whose
// remote-tracking ref did not resolve, and whose observed remote value is
// therefore empty, is written CLEARED — no published branch was observed, so
// there is no remote history or PR-base relationship for this run to protect.
// Everything else is written pending.
func reparentRemoteInitialState(remoteSHAAtWrite string) string {
	if strings.TrimSpace(remoteSHAAtWrite) == "" {
		return ReparentRemoteStateCleared
	}
	return ReparentRemoteStatePending
}

// ============================================================================
// Durable IO
// ============================================================================

// LoadReparentRemoteRecord reads the record. A missing file is not an error:
// it is the ordinary "nothing pending" answer every push path needs.
func LoadReparentRemoteRecord(loc ReparentLocation) (*ReparentRemoteRecord, error) {
	path := ReparentRemoteRecordPath(loc)
	snapshot, err := scopedPushReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}
	rec, err := decodeReparentRemoteRecordBytes(loc, snapshot.data)
	if err != nil {
		return nil, err
	}
	return &rec, nil
}

func decodeReparentRemoteRecordBytes(loc ReparentLocation, data []byte) (ReparentRemoteRecord, error) {
	path := ReparentRemoteRecordPath(loc)
	var rec ReparentRemoteRecord
	decoder := yaml.NewDecoder(bytes.NewReader(data))
	decoder.KnownFields(true)
	if err := decoder.Decode(&rec); err != nil {
		return ReparentRemoteRecord{}, fmt.Errorf("the reparent remote follow-up record at %s does not decode: %w", path, err)
	}
	if err := decoder.Decode(new(any)); err != io.EOF {
		return ReparentRemoteRecord{}, fmt.Errorf("the reparent remote follow-up record at %s has trailing data", path)
	}
	if rec.RecordVersion > ReparentRemoteRecordVersion {
		return ReparentRemoteRecord{}, reparentRefusal(ReparentRefusalStateUnsupported, fmt.Sprintf(
			"the reparent remote follow-up record at %s records record_version %d; this release supports %d",
			path, rec.RecordVersion, ReparentRemoteRecordVersion))
	}
	if err := validateReparentRemoteRecord(loc, rec); err != nil {
		return ReparentRemoteRecord{}, err
	}
	return rec, nil
}

func validReparentRemoteOID(oid string) bool {
	return (len(oid) == 40 || len(oid) == 64) && stackStatusObjectID.MatchString(oid)
}

func validateReparentRemoteRecord(loc ReparentLocation, rec ReparentRemoteRecord) error {
	invalid := func(detail string) error {
		return reparentRefusal(ReparentRefusalStateCorrupt, fmt.Sprintf(
			"the reparent remote follow-up record at %s is invalid: %s",
			ReparentRemoteRecordPath(loc), detail))
	}
	if rec.RecordVersion != ReparentRemoteRecordVersion {
		return invalid(fmt.Sprintf("record_version must equal %d, got %d", ReparentRemoteRecordVersion, rec.RecordVersion))
	}
	if rec.Feature == "" || rec.Feature != loc.Feature {
		return invalid(fmt.Sprintf("feature must equal %q, got %q", loc.Feature, rec.Feature))
	}
	if !reparentRunIDShape(rec.RunID) {
		return invalid("run_id must be exactly 32 lowercase hex characters")
	}
	if _, err := time.Parse(time.RFC3339, rec.CreatedAt); err != nil {
		return invalid("created_at must be RFC3339")
	}
	if len(rec.Entries) == 0 {
		return invalid("entries must be non-empty")
	}
	seen := map[string]bool{}
	for i, entry := range rec.Entries {
		label := fmt.Sprintf("entries[%d]", i)
		if entry.Name == "" || entry.GitBranch == "" {
			return invalid(label + " requires non-empty name and git_branch")
		}
		if seen[entry.Name] {
			return invalid(fmt.Sprintf("entry name %q is duplicated", entry.Name))
		}
		seen[entry.Name] = true
		if entry.Remote != ReparentRemoteName {
			return invalid(fmt.Sprintf("%s.remote must be %q", label, ReparentRemoteName))
		}
		wantRef := "refs/remotes/" + ReparentRemoteName + "/" + entry.GitBranch
		if entry.RemoteRef != wantRef {
			return invalid(fmt.Sprintf("%s.remote_ref must be %q", label, wantRef))
		}
		if !validReparentRemoteOID(entry.NewTipSHA) {
			return invalid(label + ".new_tip_sha must be a lowercase 40- or 64-hex object id")
		}
		if entry.RemoteSHAAtWrite != "" && !validReparentRemoteOID(entry.RemoteSHAAtWrite) {
			return invalid(label + ".remote_sha_at_write must be empty or a lowercase 40- or 64-hex object id")
		}
		switch entry.State {
		case ReparentRemoteStatePending:
			if entry.RemoteSHAAtWrite == "" {
				return invalid(label + " cannot be pending without remote_sha_at_write")
			}
		case ReparentRemoteStateCleared:
		default:
			return invalid(label + ".state must be pending or cleared")
		}
	}
	return nil
}

// SaveReparentRemoteRecord writes the record durably at 0600.
func SaveReparentRemoteRecord(loc ReparentLocation, rec ReparentRemoteRecord) error {
	data, err := marshalReparentRemoteRecord(loc, rec)
	if err != nil {
		return err
	}
	return WriteReparentRemoteRecordBytes(loc, data)
}

func marshalReparentRemoteRecord(loc ReparentLocation, rec ReparentRemoteRecord) ([]byte, error) {
	rec.RecordVersion = ReparentRemoteRecordVersion
	if rec.CreatedAt == "" {
		rec.CreatedAt = reparentNow()
	}
	if err := validateReparentRemoteRecord(loc, rec); err != nil {
		return nil, err
	}
	data, err := yaml.Marshal(&rec)
	if err != nil {
		return nil, fmt.Errorf("marshal reparent remote follow-up record: %w", err)
	}
	return data, nil
}

// WriteReparentRemoteRecordBytes restores or writes exact record bytes through
// the same durable boundary as the normal encoder.
func WriteReparentRemoteRecordBytes(loc ReparentLocation, data []byte) error {
	return durableWriteFileFault(SyncIOWriteReparentRemote, ReparentRemoteRecordPath(loc), data, 0600)
}

// ReadReparentRemoteRecordBytes validates and returns the exact bytes on disk.
// A missing record is (nil, false, nil).
func ReadReparentRemoteRecordBytes(loc ReparentLocation) ([]byte, bool, error) {
	path := ReparentRemoteRecordPath(loc)
	snapshot, err := scopedPushReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil, false, nil
	}
	if err != nil {
		return nil, false, err
	}
	if _, err := LoadReparentRemoteRecord(loc); err != nil {
		return nil, true, err
	}
	return snapshot.data, true, nil
}

// RemoveReparentRemoteRecord deletes the record file. An absent file is
// success.
func RemoveReparentRemoteRecord(loc ReparentLocation) error {
	path := ReparentRemoteRecordPath(loc)
	if err := syncIOFault(SyncIORemoveReparentRemote, path); err != nil {
		return err
	}
	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	if err := syncIOFault(SyncIORemoveReparentRemote, path); err != nil {
		return err
	}
	return syncDir(filepath.Dir(path))
}

// MergeReparentRemoteRecord folds this run's entries into whatever record
// already exists. A record can outlive its run by design, so a previous run's
// still-pending entry for ANOTHER branch is preserved verbatim. For the same
// branch, the new rewrite replaces topology fields, but a temporarily missing
// tracking ref cannot erase older positive publication evidence.
func MergeReparentRemoteRecord(existing *ReparentRemoteRecord, incoming ReparentRemoteRecord) ReparentRemoteRecord {
	incoming.Entries = append([]ReparentRemoteEntry(nil), incoming.Entries...)
	if existing == nil {
		incoming.RecordVersion = ReparentRemoteRecordVersion
		return incoming
	}
	out := ReparentRemoteRecord{
		RecordVersion: ReparentRemoteRecordVersion,
		Feature:       incoming.Feature,
		RunID:         incoming.RunID,
		CreatedAt:     incoming.CreatedAt,
	}
	incomingByName := make(map[string]int, len(incoming.Entries))
	for i := range incoming.Entries {
		incomingByName[incoming.Entries[i].Name] = i
	}
	for _, e := range existing.Entries {
		index, replaced := incomingByName[e.Name]
		if replaced {
			next := &incoming.Entries[index]
			if e.Pending() && e.Published() && !next.Pending() && !next.Published() {
				next.RemoteSHAAtWrite = e.RemoteSHAAtWrite
				next.State = ReparentRemoteStatePending
			}
			continue
		}
		out.Entries = append(out.Entries, e)
	}
	out.Entries = append(out.Entries, incoming.Entries...)
	return out
}

// RemoveReparentRemoteEntries deletes exactly the named entries — the ones a
// pre-commit --abort created (§11.8 step 7) — and deletes the file when it
// empties. The names come from the state artifact's remote_followup_entries,
// which is the only authoritative statement of what THIS run wrote.
func RemoveReparentRemoteEntries(loc ReparentLocation, names []string) error {
	rec, err := LoadReparentRemoteRecord(loc)
	if err != nil || rec == nil {
		return err
	}
	drop := make(map[string]bool, len(names))
	for _, n := range names {
		drop[n] = true
	}
	kept := rec.Entries[:0]
	for _, e := range rec.Entries {
		if drop[e.Name] {
			continue
		}
		kept = append(kept, e)
	}
	rec.Entries = kept
	if len(rec.Entries) == 0 {
		return RemoveReparentRemoteRecord(loc)
	}
	return SaveReparentRemoteRecord(loc, *rec)
}

// ============================================================================
// §12.2 guidance
// ============================================================================

// The fixed guidance sentences. They never recommend a plain `git push`,
// never bind --force-with-lease to a freshly observed remote tip, and never
// imply that --force-if-includes strengthens an explicit lease.
const (
	ReparentGuidanceNoRemoteChange = "tws changed no remote ref and no pull request."
	ReparentGuidanceOrder          = "retarget the pull request first, then fetch and integrate remote work, then publish."
	ReparentGuidanceForcePrefix    = "if you force publish, use: git push --force-with-lease --force-if-includes origin "
)

// ReparentRemoteGuidance builds remote.guidance — the same ordered lines the
// success output prints.
//
// Items 1 and 4 are single lines; items 2 and 3 repeat per qualifying row.
// Item 5 names a branch, so it repeats once per row that actually has a
// remote ref to publish to (and, when none does, once for the target's own
// branch): a single line naming one branch of many would tell an operator to
// force-publish the wrong one.
func ReparentRemoteGuidance(rows []ReparentPlanRemoteRow) []string {
	out := []string{ReparentGuidanceNoRemoteChange}
	for _, r := range rows {
		if r.PRBaseBefore == nil || r.PRBaseAfter == nil || *r.PRBaseBefore == *r.PRBaseAfter {
			continue
		}
		out = append(out, fmt.Sprintf("%s: PR base %s -> %s", r.Name, *r.PRBaseBefore, *r.PRBaseAfter))
	}
	for _, r := range rows {
		if r.Divergence == "none" || r.RemoteRef == nil {
			continue
		}
		out = append(out, fmt.Sprintf(
			"%s: local and %s have diverged; the remote still holds the pre-reparent history.", r.Name, *r.RemoteRef))
	}
	out = append(out, ReparentGuidanceOrder)

	published := false
	for _, r := range rows {
		if r.RemoteRef == nil {
			continue
		}
		published = true
		out = append(out, ReparentGuidanceForcePrefix+r.GitBranch)
	}
	if !published && len(rows) > 0 {
		out = append(out, ReparentGuidanceForcePrefix+rows[0].GitBranch)
	}
	return out
}

// reparentProviderHint derives §7.9's provider_hint from the local origin URL
// and from nothing else. No provider is contacted, and an unrecognized URL is
// "generic", never a guess at a vendor.
func reparentProviderHint(originURL string) string {
	u := strings.ToLower(strings.TrimSpace(originURL))
	switch {
	case u == "":
		return "unknown"
	case strings.Contains(u, "github.com"):
		return "github"
	case strings.Contains(u, "dev.azure.com"), strings.Contains(u, "visualstudio.com"):
		return "azure-devops"
	default:
		return "generic"
	}
}

// ============================================================================
// §12.5 clearing, without provider access
// ============================================================================

// ReparentRemoteObservation is which of §12.5's local observations cleared an
// entry. It is published so a mutating route can say why it cleared a row.
type ReparentRemoteObservation string

const (
	ReparentRemoteObservationNone      ReparentRemoteObservation = ""
	ReparentRemoteObservationPublished ReparentRemoteObservation = "remote-tip-equals-new-tip"
	ReparentRemoteObservationContains  ReparentRemoteObservation = "remote-contains-new-tip"
	ReparentRemoteObservationEntryGone ReparentRemoteObservation = "entry-absent-or-archived"
)

// ObserveReparentRemoteClear evaluates §12.5 observations 1, 2 and 4 for one
// entry, locally, with no fetch and no network. Observation 3 (a tws push
// succeeded) is the push path's own follow-up: it re-reads the tracking ref
// after its push and re-enters here, so there is exactly one clearing ladder.
//
// A missing remote-tracking ref is deliberately NOT a clearing observation:
// §12.5's initial-state rule already cleared the never-published rows, and a
// published row whose tracking ref later disappears stays pending until the
// operator resolves the remote state.
func ObserveReparentRemoteClear(repoDir string, e ReparentRemoteEntry, stack *Stack) (ReparentRemoteObservation, error) {
	return observeReparentRemoteClear(repoDir, e, stack, false)
}

func observeReparentRemoteClear(repoDir string, e ReparentRemoteEntry, stack *Stack, localOnly bool) (ReparentRemoteObservation, error) {
	if stack != nil {
		found := false
		for _, entry := range stack.Branches {
			if entry.Name != e.Name {
				continue
			}
			found = true
			if entry.Archived {
				return ReparentRemoteObservationEntryGone, nil
			}
		}
		if !found {
			return ReparentRemoteObservationEntryGone, nil
		}
	}
	ref := e.RemoteRef
	if ref == "" {
		ref = "refs/remotes/" + ReparentRemoteName + "/" + e.GitBranch
	}
	var live string
	var ok bool
	var err error
	if localOnly {
		live, err = scopedPushRef(repoDir, ref)
		ok = live != ""
	} else {
		live, ok, err = reparentResolveRef(repoDir, ref)
	}
	if err != nil {
		return ReparentRemoteObservationNone, err
	}
	if !ok {
		return ReparentRemoteObservationNone, nil
	}
	if live == e.NewTipSHA {
		return ReparentRemoteObservationPublished, nil
	}
	if e.NewTipSHA == "" {
		return ReparentRemoteObservationNone, nil
	}
	var contains bool
	if localOnly {
		contains, err = scopedPushAncestor(repoDir, e.NewTipSHA, live)
	} else {
		contains, err = reparentIsAncestor(repoDir, e.NewTipSHA, live)
	}
	if err != nil {
		return ReparentRemoteObservationNone, err
	}
	if contains {
		return ReparentRemoteObservationContains, nil
	}
	return ReparentRemoteObservationNone, nil
}

// ReparentRemoteClear is one evaluated row of a clearing pass.
type ReparentRemoteClear struct {
	Name        string
	Observation ReparentRemoteObservation
	Cleared     bool
}

type ReparentRemoteClearTransition struct {
	Clears        []ReparentRemoteClear
	Source        []byte
	SourcePresent bool
	Target        []byte
	TargetPresent bool
	Changed       bool
}

// EvaluateReparentRemoteClears computes, IN MEMORY, which pending entries are
// now clear. It writes nothing, so a read-only surface that wants the facts
// may call it; §11.10 and §12.5 forbid those surfaces from persisting the
// result.
func EvaluateReparentRemoteClears(repoDir string, rec ReparentRemoteRecord, stack *Stack) ([]ReparentRemoteClear, error) {
	return EvaluateSelectedReparentRemoteClears(repoDir, rec, stack, nil)
}

// EvaluateSelectedReparentRemoteClears keeps the complete record and stack for
// validation/existence semantics, but never probes an unselected row. A nil
// selection retains the all-row behavior of non-publication callers.
func EvaluateSelectedReparentRemoteClears(repoDir string, rec ReparentRemoteRecord, stack *Stack, selected map[string]bool) ([]ReparentRemoteClear, error) {
	return evaluateSelectedReparentRemoteClears(repoDir, rec, stack, selected, false)
}

func evaluateSelectedReparentRemoteClears(repoDir string, rec ReparentRemoteRecord, stack *Stack, selected map[string]bool, localOnly bool) ([]ReparentRemoteClear, error) {
	if selected != nil {
		if err := validateReparentRemoteRecord(ReparentLocation{Feature: rec.Feature}, rec); err != nil {
			return nil, err
		}
	}
	out := make([]ReparentRemoteClear, 0, len(rec.Entries))
	for _, e := range rec.Entries {
		if selected != nil && !selected[e.Name] {
			continue
		}
		if !e.Pending() {
			out = append(out, ReparentRemoteClear{Name: e.Name, Cleared: true})
			continue
		}

		entryRepo := repoDir
		repoToken := e.Repo
		if stack != nil {
			if current := GetBranch(*stack, e.Name); current.Name != "" {
				repoToken = current.Repo
			}
		}
		if strings.TrimSpace(repoToken) != "" {
			entryRepo = canonicalize(repoToken)
		}
		if selected != nil && entryRepo == "" {
			if stack == nil {
				return nil, errors.New("selected reparent follow-up has no verified repository context")
			}
			if current := GetBranch(*stack, e.Name); current.Name != "" && !current.Archived {
				return nil, errors.New("selected reparent follow-up has no verified repository context")
			}
		}
		obs, err := observeReparentRemoteClear(entryRepo, e, stack, localOnly)
		if err != nil {
			return nil, err
		}
		out = append(out, ReparentRemoteClear{
			Name:        e.Name,
			Observation: obs,
			Cleared:     obs != ReparentRemoteObservationNone,
		})
	}
	return out, nil
}

func BuildReparentRemoteClearTransition(loc ReparentLocation, repoDir string, stack *Stack) (ReparentRemoteClearTransition, error) {
	return BuildSelectedReparentRemoteClearTransition(loc, repoDir, stack, nil)
}

func BuildSelectedReparentRemoteClearTransition(loc ReparentLocation, repoDir string, stack *Stack, selected map[string]bool) (ReparentRemoteClearTransition, error) {
	source, present, err := ReadReparentRemoteRecordBytes(loc)
	if err != nil || !present {
		return ReparentRemoteClearTransition{SourcePresent: present, TargetPresent: present}, err
	}
	rec, err := decodeReparentRemoteRecordBytes(loc, source)
	if err != nil {
		return ReparentRemoteClearTransition{}, err
	}
	clears, err := EvaluateSelectedReparentRemoteClears(repoDir, rec, stack, selected)
	if err != nil {
		return ReparentRemoteClearTransition{}, err
	}
	byName := make(map[string]ReparentRemoteClear, len(clears))
	for _, clear := range clears {
		byName[clear.Name] = clear
	}
	changed := false
	for i := range rec.Entries {
		if rec.Entries[i].Pending() && byName[rec.Entries[i].Name].Cleared {
			rec.Entries[i].State = ReparentRemoteStateCleared
			changed = true
		}
	}
	transition := ReparentRemoteClearTransition{
		Clears: clears, Source: source, SourcePresent: true,
		Target: source, TargetPresent: true, Changed: changed,
	}
	if !changed {
		return transition, nil
	}
	if rec.AllCleared() {
		transition.Target = nil
		transition.TargetPresent = false
		return transition, nil
	}
	target, err := marshalReparentRemoteRecord(loc, rec)
	if err != nil {
		return ReparentRemoteClearTransition{}, err
	}
	transition.Target = target
	return transition, nil
}

// ApplyReparentRemoteClears is the MUTATING half: it persists the cleared
// states and deletes the file once every entry is cleared. Only a real push
// path, a push-enabled sync, a fresh reparent execution or a reparent
// recovery route may call it; every read-only surface must use
// EvaluateReparentRemoteClears instead.
func ApplyReparentRemoteClears(loc ReparentLocation, repoDir string, stack *Stack) ([]ReparentRemoteClear, error) {
	return ApplySelectedReparentRemoteClears(loc, repoDir, stack, nil)
}

func ApplySelectedReparentRemoteClears(loc ReparentLocation, repoDir string, stack *Stack, selected map[string]bool) ([]ReparentRemoteClear, error) {
	transition, err := BuildSelectedReparentRemoteClearTransition(loc, repoDir, stack, selected)
	if err != nil || !transition.Changed {
		return transition.Clears, err
	}
	if transition.TargetPresent {
		err = WriteReparentRemoteRecordBytes(loc, transition.Target)
	} else {
		err = RemoveReparentRemoteRecord(loc)
	}
	return transition.Clears, err
}

// ============================================================================
// Rule R-PUSH decision values (§12.4, §12.4a) — data only
// ============================================================================

// ReparentPushDecision is what rule R-PUSH says about ONE entry of a push
// invocation. Its zero value is "this entry is not in any pending record",
// which MUST reproduce today's argv, output and exit status byte-for-byte —
// that is why the push-path integration can pass a zero value and change
// nothing.
type ReparentPushDecision struct {
	// Applies is true only for an entry listed pending in the record.
	Applies bool

	// WarnLine is the single anchored stderr line printed before the push.
	WarnLine string

	// ForceIfIncludes is true exactly when the argv must become
	// `--force-with-lease --force-if-includes` — the BARE lease plus the
	// inclusion check, never an explicit --force-with-lease=<ref>:<sha>.
	ForceIfIncludes bool

	// DryRunSuffix is what `tws push --dry-run` renders instead of pushing.
	DryRunSuffix string
}

// ReparentPushDecisionFor computes the decision for one entry. A record that
// is absent, or that does not list the entry, produces the zero value.
func ReparentPushDecisionFor(rec *ReparentRemoteRecord, name string) ReparentPushDecision {
	if rec == nil {
		return ReparentPushDecision{}
	}
	e, ok := rec.Entry(name)
	if !ok || !e.Pending() {
		return ReparentPushDecision{}
	}
	baseChange := ""
	if e.PRBaseBefore != "" && e.PRBaseAfter != "" {
		baseChange = fmt.Sprintf(" (%s -> %s)", e.PRBaseBefore, e.PRBaseAfter)
	}
	return ReparentPushDecision{
		Applies: true,
		WarnLine: fmt.Sprintf(
			"reparent-remote: %s was reparented%s; retarget the pull request before publishing",
			e.Name, baseChange),
		ForceIfIncludes: true,
		DryRunSuffix:    "(would push --force-with-lease --force-if-includes)",
	}
}

// ReparentPushPreflight is rule R-PUSH's INVOCATION-WIDE gate, evaluated once
// before the first real push. Pushing half a stack and only then discovering
// the lease cannot be strengthened is precisely the outcome it exists to
// prevent, which is why it is never per-entry.
type ReparentPushPreflight struct {
	// Refuse is true when at least one published, pending entry of this
	// invocation cannot be pushed with a strengthened lease, or when the
	// record itself could not be trusted.
	Refuse bool

	// LoadFailure distinguishes "the record could not be read" from "a lease
	// cannot be strengthened", and LoadKind carries the loader's OWN verdict
	// so every push path reports the same kind for the same file: a greater
	// record_version is reparent-state-unsupported, a document that does not
	// decode is reparent-state-corrupt.
	LoadFailure bool
	LoadKind    ReparentRefusalKind

	// Failing lists the entry names that failed, in invocation order.
	Failing []string

	// Detail is the refusal sentence: it names the failing entries, the
	// required Git version, the fetch remedy and the manual alternative.
	Detail string
}

// Refusal projects the preflight into the typed refusal a real push route
// returns. A dry run reports the same verdict as a diagnostic instead
// (§12.4a rule 2) and still exits 0.
func (p ReparentPushPreflight) Refusal() *ReparentRefusalError {
	if !p.Refuse {
		return nil
	}
	if p.LoadFailure {
		return reparentRefusal(p.loadKindOrCorrupt(), p.Detail)
	}
	return reparentRefusal(ReparentRefusalRemoteFollowupUnsafeLease, p.Detail)
}

// DryRunLine is §12.4a rule 2's diagnostic form of the same verdict.
func (p ReparentPushPreflight) DryRunLine() string {
	if !p.Refuse {
		return ""
	}
	kind := ReparentRefusalRemoteFollowupUnsafeLease
	if p.LoadFailure {
		kind = p.loadKindOrCorrupt()
	}
	return fmt.Sprintf("reparent-remote: would refuse: %s: %s", kind, p.Detail)
}

// loadKindOrCorrupt defaults an unrecorded load verdict to the conservative
// corrupt kind rather than to a lease problem it is not.
func (p ReparentPushPreflight) loadKindOrCorrupt() ReparentRefusalKind {
	if p.LoadKind != "" {
		return p.LoadKind
	}
	return ReparentRefusalStateCorrupt
}

// ReparentPushEntryProbe is one entry's measured input to the preflight: the
// name the invocation would push and whether its remote-tracking ref resolves
// right now.
type ReparentPushEntryProbe struct {
	Name             string
	TrackingResolves bool
}

// EvaluateReparentPushPreflight is rule R-PUSH step 2. It fails for a
// PUBLISHED pending entry (one whose remote_sha_at_write is non-empty) when
// either the Git binary cannot strengthen the lease or the tracking ref does
// not resolve. An unpublished entry was already written cleared, so it can
// never reach this gate.
func EvaluateReparentPushPreflight(rec *ReparentRemoteRecord, caps ReparentGitCapabilities, probes []ReparentPushEntryProbe) ReparentPushPreflight {
	if rec == nil {
		return ReparentPushPreflight{}
	}
	var failing []string
	var reasons []string
	for _, p := range probes {
		e, ok := rec.Entry(p.Name)
		if !ok || !e.Pending() || !e.Published() {
			continue
		}
		switch {
		case !caps.CapForceIfIncludes:
			failing = append(failing, p.Name)
			reasons = append(reasons, fmt.Sprintf("%s: this git cannot pass --force-if-includes", p.Name))
		case !p.TrackingResolves:
			failing = append(failing, p.Name)
			reasons = append(reasons, fmt.Sprintf("%s: %s does not resolve", p.Name, e.RemoteRef))
		}
	}
	if len(failing) == 0 {
		return ReparentPushPreflight{}
	}
	return ReparentPushPreflight{
		Refuse:  true,
		Failing: failing,
		Detail: fmt.Sprintf(
			"%s; a reparented branch is published only with git >= 2.30's --force-if-includes and a resolving remote-tracking ref. Run `git fetch %s` and retry, or publish by hand with: git push --force-with-lease --force-if-includes %s <branch>",
			strings.Join(reasons, "; "), ReparentRemoteName, ReparentRemoteName),
	}
}

// ============================================================================
// ReparentPushEnvelope (§12.4, §12.4a) — the push-path integration seam
//
// Every one of the three live bare-lease push paths loads ONE envelope per
// invocation, before its first real push, and then asks it two questions: the
// invocation-wide preflight and the per-entry decision. An invocation with no
// record holds an envelope whose Record is nil, whose Preflight never refuses
// and whose Decision is always the zero value — which is exactly rule 1's
// "behaviour is byte-identical to today".
// ============================================================================

// ReparentPushEnvelope is one push invocation's whole rule R-PUSH state.
type ReparentPushEnvelope struct {
	Loc      ReparentLocation
	RepoDir  string
	Record   *ReparentRemoteRecord
	Selected map[string]bool

	// Err is the typed load verdict. It is nil for "no record at all" — the
	// only inert absence — and non-nil for a record that EXISTS and could not
	// be trusted: an unsupported record_version, a document that does not
	// decode, or an unreadable file.
	Err error
}

// LoadReparentPushEnvelope reads the record ONCE and keeps the verdict.
//
// A record that exists but cannot be read is NOT "no record". Treating it as
// one would silently restore the bare `--force-with-lease` argv for branches
// this tool knows were rewritten, which is the precise outcome rule R-PUSH
// exists to prevent — and it would do so on the strength of a file the tool
// failed to parse. Only os.ErrNotExist is inert; every other verdict makes
// the invocation refuse before its first push.
func LoadReparentPushEnvelope(loc ReparentLocation, repoDir string) ReparentPushEnvelope {
	env := ReparentPushEnvelope{Loc: loc, RepoDir: repoDir}
	if loc.Feature == "" {
		return env
	}
	rec, err := LoadReparentRemoteRecord(loc)
	if err != nil {
		env.Err = err
		return env
	}
	env.Record = rec
	return env
}

// PrepareReparentPushEnvelope applies §12.5 observations before lease
// capability preflight. Real push routes persist and reload under their
// invocation lock; dry-run callers request an in-memory projection only.
func PrepareReparentPushEnvelope(loc ReparentLocation, repoDir string, stack *Stack, persist bool) (ReparentPushEnvelope, error) {
	return PrepareSelectedReparentPushEnvelope(loc, repoDir, stack, persist, nil)
}

// PrepareSelectedReparentPushEnvelope is the scoped publication seam. Callers
// must pass the full stack, including unavailable and unselected neighbors.
func PrepareSelectedReparentPushEnvelope(loc ReparentLocation, repoDir string, stack *Stack, persist bool, selected map[string]bool) (ReparentPushEnvelope, error) {
	return prepareSelectedReparentPushEnvelope(loc, repoDir, stack, persist, selected, false)
}

// PrepareLocalSelectedReparentPushEnvelope additionally forbids lazy object
// fetching. Standalone publication uses this strictly local projection; the
// existing sync/legacy paths keep their Git compatibility and bare-lease argv.
func PrepareLocalSelectedReparentPushEnvelope(loc ReparentLocation, repoDir string, stack *Stack, selected map[string]bool) (ReparentPushEnvelope, error) {
	return prepareSelectedReparentPushEnvelope(loc, repoDir, stack, false, selected, true)
}

func prepareSelectedReparentPushEnvelope(loc ReparentLocation, repoDir string, stack *Stack, persist bool, selected map[string]bool, localOnly bool) (ReparentPushEnvelope, error) {
	env := LoadReparentPushEnvelope(loc, repoDir)
	env.Selected = selected
	if env.Err != nil || env.Record == nil {
		return env, nil
	}
	if persist {
		if _, err := ApplySelectedReparentRemoteClears(loc, repoDir, stack, selected); err != nil {
			return env, err
		}
		reloaded := LoadReparentPushEnvelope(loc, repoDir)
		reloaded.Selected = selected
		if refusal := reloaded.LoadRefusal(); refusal != nil {
			return reloaded, AnchorReparentRefusal(refusal)
		}
		return reloaded, nil
	}
	clears, err := evaluateSelectedReparentRemoteClears(repoDir, *env.Record, stack, selected, localOnly)
	if err != nil {
		return env, err
	}
	rec := *env.Record
	rec.Entries = append([]ReparentRemoteEntry{}, env.Record.Entries...)
	byName := make(map[string]ReparentRemoteClear, len(clears))
	for _, clear := range clears {
		byName[clear.Name] = clear
	}
	for i := range rec.Entries {
		if rec.Entries[i].Pending() && byName[rec.Entries[i].Name].Cleared {
			rec.Entries[i].State = ReparentRemoteStateCleared
		}
	}
	env.Record = &rec
	return env, nil
}

// Failed reports whether the record exists and could not be trusted.
func (e ReparentPushEnvelope) Failed() bool { return e.Err != nil }

// LoadRefusal projects an untrusted record into the refusal every real push
// path returns before pushing anything. It is nil when the record loaded, or
// when there is none at all.
func (e ReparentPushEnvelope) LoadRefusal() *ReparentRefusalError {
	if e.Err == nil {
		return nil
	}
	var typed *ReparentRefusalError
	if errors.As(e.Err, &typed) {
		return typed
	}
	return reparentRefusal(ReparentRefusalStateCorrupt, fmt.Sprintf(
		"the reparent remote follow-up record at %s could not be read, so tws cannot tell which branches were reparented: %v. Inspect or remove it, then retry",
		ReparentRemoteRecordPath(e.Loc), e.Err))
}

// Active reports whether this invocation has any pending record at all.
func (e ReparentPushEnvelope) Active() bool {
	return e.Record != nil && len(e.Record.PendingEntries()) > 0
}

// Decision is rule R-PUSH steps 3 and 4 for one entry.
func (e ReparentPushEnvelope) Decision(name string) ReparentPushDecision {
	return ReparentPushDecisionFor(e.Record, name)
}

// Preflight is rule R-PUSH step 2, evaluated ONCE over every entry this
// invocation would push, before the first of them is pushed. names is the
// invocation's own push order, so Failing reports in that order.
func (e ReparentPushEnvelope) Preflight(names []string) ReparentPushPreflight {
	if refusal := e.LoadRefusal(); refusal != nil {
		return ReparentPushPreflight{Refuse: true, Detail: refusal.Detail, LoadFailure: true, LoadKind: refusal.Kind}
	}
	if !e.Active() {
		return ReparentPushPreflight{}
	}
	probes := make([]ReparentPushEntryProbe, 0, len(names))
	for _, name := range names {
		probes = append(probes, e.ProbeEntry(e.RepoDir, name))
	}
	return e.PreflightProbes(probes)
}

// ProbeEntry measures ONE entry's remote-tracking ref in the Git context that
// entry would actually be pushed from. External push loops choose that context
// per entry (a worktree, or StackEntry.Repo), so the probe takes it explicitly
// rather than assuming the envelope's own directory.
func (e ReparentPushEnvelope) ProbeEntry(repoDir, name string) ReparentPushEntryProbe {
	probe := ReparentPushEntryProbe{Name: name}
	if e.Record == nil {
		return probe
	}
	entry, ok := e.Record.Entry(name)
	if !ok || !entry.Pending() {
		return probe
	}
	ref := entry.RemoteRef
	if ref == "" {
		ref = "refs/remotes/" + ReparentRemoteName + "/" + entry.GitBranch
	}
	dir := repoDir
	if dir == "" {
		dir = e.RepoDir
	}
	_, resolves, err := reparentResolveRef(dir, ref)
	probe.TrackingResolves = resolves && err == nil
	return probe
}

// PreflightProbes is the pure half of step 2 over already-measured probes. An
// untrusted record refuses here too, so every caller that runs the
// invocation-wide preflight — which is every real push path — fails closed
// without needing its own branch for it.
func (e ReparentPushEnvelope) PreflightProbes(probes []ReparentPushEntryProbe) ReparentPushPreflight {
	if refusal := e.LoadRefusal(); refusal != nil {
		return ReparentPushPreflight{Refuse: true, Detail: refusal.Detail, LoadFailure: true, LoadKind: refusal.Kind}
	}
	if !e.Active() {
		return ReparentPushPreflight{}
	}
	version, _ := ProbeGitVersion()
	return EvaluateReparentPushPreflight(e.Record, ReparentGitCapabilitiesForVersion(version), probes)
}

// PersistClears re-observes after successful pushes so observation 3 can clear
// a row whose tracking ref advanced during the push. The mandatory preflight
// clearing pass already ran through PrepareReparentPushEnvelope. RepoDir stays
// the workspace/default repository; each record entry with Repo set overrides
// it inside EvaluateReparentRemoteClears.
func (e ReparentPushEnvelope) PersistClears(stack *Stack) error {
	if e.Record == nil || e.Err != nil {
		return e.Err
	}
	_, err := ApplySelectedReparentRemoteClears(e.Loc, e.RepoDir, stack, e.Selected)
	return err
}

